{
  "swagger": "2.0",
  "info": {
    "title": "Provider API for Freight Booking for Confirmation",
    "description": "Provides functionality for managing the freight booking request confirmation process when integrating SAP Business Network for Logistics with external systems.\nThis specification describes the API from the perspective of SAP Business Network for Logistics as the provider of the API.\nOther systems call the defined endpoints within SAP Business Network for Logistics.\n",
    "version": "1.0.16",
    "contact": {
      "name": "lbn@sap.com"
    },
    "termsOfService": ""
  },
  "x-sap-shortText": "Enables carriers to manage the freight booking process.",
  "x-servers": [
    {
      "url": "https://api.logistics.eu.business-network.cloud.sap/http/v1",
      "description": "FreightBooking API endpoint for EU10 data center"
    },
    {
      "url": "https://api.logistics.us.business-network.cloud.sap/http/v1",
      "description": "FreightBooking API endpoint for US20 data center"
    }
  ],
  "host": "hostname",
  "externalDocs": {
    "description": "Click here to access detailed implementation documentation.",
    "url": "https://help.sap.com/doc/e1b2026259d84fc29e6e6760da815011/LBN/en-US/73334914c4c2462a9a6a313c1dcf6678.html"
  },
  "securityDefinitions": {
    "eu10": {
      "type": "oauth2",
      "description": "To use the EU10 data center API, you must obtain the OAuth client credentials (client ID and secret). \nTo get the OAuth client credentials, create a customer incident on SAP support portal with the component as SBN-LBN-INT. \nProvide the SAP Business Network for Logistics ID created for your account and the email address to receive your client credentials. \nSpecify the target integration platform as ‘Multi-Cloud (new)’ and the title as ‘SAP BN4L Integration Platform Migration: Request for new OAuth 2.0 credential’. \nOnce you receive the credentials, pass the details to SAP HANA Cloud Platform token endpoint to obtain an access token.\n",
      "tokenUrl": "https://bn4lintegrationsuiteliveeu10-d2q5jmpt.authentication.eu10.hana.ondemand.com/oauth/token?grant_type=client_credentials",
      "flow": "application",
      "scopes": {
        "{identityzone}.custom-activity_view": "Get custom activity step information.",
        "{identityzone}.custom-activity_confirm": "Confirm custom activity step information retrieval."
      }
    },
    "us20": {
      "type": "oauth2",
      "description": "To use the US20 data center API, you must obtain the OAuth client credentials (client ID and secret). \nTo get the OAuth client credentials, create a customer incident on SAP support portal with the component as SBN-LBN-INT. \nProvide the SAP Business Network for Logistics ID created for your account and the email address to receive your client credentials. \nSpecify the target integration platform as ‘Multi-Cloud (new)’ and the title as ‘SAP BN4L Integration Platform Migration: Request for new OAuth 2.0 credential’. \nOnce you receive the credentials, pass the details to SAP HANA Cloud Platform token endpoint to obtain an access token.\n",
      "tokenUrl": "https://bn4lintegrationsuiteliveus20-0gohdecj.authentication.us20.hana.ondemand.com/oauth/token?grant_type=client_credentials",
      "flow": "application",
      "scopes": {
        "{identityzone}.custom-activity_view": "Get custom activity step information.",
        "{identityzone}.custom-activity_confirm": "Confirm custom activity step information retrieval."
      }
    }
  },
  "security": [
    {
      "eu10": [
        "{identityzone}.custom-activity_view",
        "{identityzone}.custom-activity_confirm"
      ]
    },
    {
      "us20": [
        "{identityzone}.custom-activity_view",
        "{identityzone}.custom-activity_confirm"
      ]
    }
  ],
  "schemes": [
    "https"
  ],
  "produces": [
    "application/json"
  ],
  "consumes": [
    "application/json"
  ],
  "tags": [
    {
      "name": "Freight Booking Confimation"
    }
  ],
  "paths": {
    "/FreightBookingConfirmation": {
      "post": {
        "summary": "Creates a carrier response for a freight booking",
        "tags": [
          "Freight Booking Confimation"
        ],
        "consumes": [
          "application/json"
        ],
        "description": "Creates a carrier response for a freight booking in SAP Business Network for Logistics.\nWith this functionality, a carrier can confirm or reject a freight booking.\nWhen confirming, an alternative price can be proposed, if permitted by the ordering party.\nThe alternative price is the amount for which the carrier agrees to execute the transportation.\nWhen rejecting, a reason code can be provided.\n",
        "parameters": [
          {
            "in": "body",
            "name": "body",
            "description": "Carrier response to a freight booking request.",
            "required": true,
            "schema": {
              "$ref": "#/definitions/PostFreightBookingForSubcontractingCarrierResponse"
            }
          }
        ],
        "produces": [
          "application/json"
        ],
        "responses": {
          "201": {
            "description": "response created successfully",
            "schema": {
              "$ref": "#/definitions/ResponseStructure"
            }
          },
          "400": {
            "description": "Bad Request",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "401": {
            "description": "Unauthorized",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "403": {
            "description": "Forbidden",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "500": {
            "description": "Internal Server Error",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          }
        }
      }
    }
  },
  "definitions": {
    "PostFreightBookingForSubcontractingCarrierResponse": {
      "allOf": [
        {
          "type": "object",
          "required": [
            "technicalId",
            "senderParty",
            "recipientParty",
            "documentRecipientParty",
            "transportationOrderBooking"
          ],
          "properties": {
            "technicalId": {
              "type": "string",
              "maxLength": 100,
              "description": "An unique standard identifier for the freight booking.\n"
            },
            "senderParty": {
              "$ref": "#/definitions/PartyDetails"
            },
            "originatorId": {
              "$ref": "#/definitions/OriginatorId"
            },
            "recipientParty": {
              "$ref": "#/definitions/PartyDetails"
            },
            "documentRecipientParty": {
              "$ref": "#/definitions/PartyDetails"
            },
            "transportationOrderBooking": {
              "$ref": "#/definitions/FreightBookingConfirmation"
            }
          }
        }
      ]
    },
    "FreightBookingConfirmation": {
      "type": "object",
      "required": [
        "baseBusinessTransactionDocumentReference",
        "acceptanceStatusCode"
      ],
      "properties": {
        "freightBookingId": {
          "$ref": "#/definitions/FreightBookingId"
        },
        "externalDocumentIdentifier": {
          "$ref": "#/definitions/ExternalDocumentIdentifier"
        },
        "ordinalNumber": {
          "$ref": "#/definitions/OrdinalNumber"
        },
        "acceptanceStatusCode": {
          "type": "string",
          "maxLength": 2,
          "enum": [
            "AP",
            "RE"
          ],
          "description": "Represents the status of an acceptance that is transmitted from a carrier to a customer, with reference to a transportation order (in this case, a freight booking) that was previously sent to that carrier.\n* AP - Confirm freight booking\n* RE - Reject freight booking\n",
          "example": "AP"
        },
        "proposalPrice": {
          "properties": {
            "value": {
              "type": "number",
              "example": 1500,
              "description": "Amount that the carrier proposes for executing a freight booking for subcontracting.",
              "x-precision": 28,
              "x-scale": 6
            },
            "currency": {
              "type": "string",
              "example": "USD",
              "description": "Format must be compliant with SAP Global Data Type `CurrencyCode` (`listID` = `4217`, `listAgencyID` = `5`). [Codelist](https://help.sap.com/docs/SAP_LBN_FC_OPTION/40f43410e8a64dc98792a5e610e81017/c5ff86c3b2c744b4aab2ade9d9b1f05e.html)\n",
              "maxLength": 3
            }
          }
        },
        "orderRejectionReasonCode": {
          "type": "string",
          "maxLength": 10,
          "enum": [
            "LBN_CAPA",
            "LBN_OTHERS",
            "LBN_PRICE",
            "LBN_TIME"
          ],
          "description": "Represents the reason for rejecting a freight booking.\n* LBN_CAPA - No capacity\n* LBN_OTHERS - Other\n* LBN_PRICE - Price\n* LBN_TIME - No time\n",
          "example": "LBN_CAPA"
        },
        "totalBookedCapacityWeightConfirmedQuantity": {
          "type": "object",
          "properties": {
            "value": {
              "type": "number",
              "example": 100
            },
            "unit": {
              "description": "Unit Code [codelist](https://help.sap.com/docs/business-network-freight-collaboration/code-lists/unit-of-measure-weight)                  \n* KGM - Kilogram\n* LBR - US pound\n* TNE - Tonne (1000 kg)\n",
              "type": "string",
              "maxLength": 3,
              "example": "KGM",
              "enum": [
                "KGM",
                "LBR",
                "TNE"
              ]
            }
          },
          "description": "Specification of the confirmed total quantity of the booked capacity weight with respect to the freight booking.\n"
        },
        "totalBookedCapacityVolumeConfirmedQuantity": {
          "type": "object",
          "properties": {
            "value": {
              "type": "number",
              "example": 10
            },
            "unit": {
              "description": "Unit Code [codelist](https://help.sap.com/docs/business-network-freight-collaboration/code-lists/unit-of-measure-volume)\n* CMQ - Cubic centimeter\n* DMQ - Cubic decimeter\n* FC - Thousand cubic foot\n* FTQ - Cubic foot\n* INQ - Cubic inch\n* LTR - Liter\n* MTQ - Cubic meter \n* YDQ - Cubic yard\n",
              "type": "string",
              "maxLength": 3,
              "example": "CMQ",
              "enum": [
                "CMQ",
                "DMQ",
                "FC",
                "FTQ",
                "INQ",
                "LTR",
                "MTQ",
                "YDQ"
              ]
            }
          },
          "description": "Specification of the confirmed total quantity of the booked capacity volume with respect to the freight booking. \n"
        },
        "totalBookedCapacityPiecesConfirmedQuantity": {
          "type": "object",
          "properties": {
            "value": {
              "type": "number",
              "example": 1
            },
            "unit": {
              "type": "string",
              "maxLength": 3,
              "description": "Format must be compliant with `Common Codes` specified in UN/CEFACT Recommendation #20. [codelist](https://help.sap.com/docs/business-network-freight-collaboration/code-lists/unit-of-measure-quantity)\n",
              "example": "PCE"
            }
          },
          "description": "Specification of the confirmed total quantity of the booked capacity of pieces with respect to the freight booking. \n"
        },
        "mainCarriageActualDepartureDateTime": {
          "$ref": "#/definitions/MainCarriageActualDepartureDateTime"
        },
        "mainCarriageActualArrivalDateTime": {
          "$ref": "#/definitions/MainCarriageActualArrivalDateTime"
        },
        "mainCarriageWeighingDueDateTime": {
          "$ref": "#/definitions/MainCarriageWeighingDueDateTime"
        },
        "waybillNotificationDueDateTime": {
          "$ref": "#/definitions/WaybillNotificationDueDateTime"
        },
        "additionalParty": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/AdditionalParty"
          }
        },
        "transportationStages": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/TransportationStage"
          },
          "description": "Information about a section of the transportation chain represented by a freight booking.\n"
        },
        "bookingCapacities": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/BookingCapacity"
          }
        },
        "baseBusinessTransactionDocumentReference": {
          "$ref": "#/definitions/BaseBusinessTransactionDocumentReference",
          "description": "A unique reference between a transportation order and the base business transaction document.\n"
        },
        "businessTransactionDocumentReferences": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/BusinessTransactionDocumentReference"
          },
          "description": "A unique reference between a transportation order and the base business transaction document.\n"
        },
        "items": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/Item"
          },
          "description": "A collection of detailed information about the goods to be transported (for example, their packaging).\n"
        },
        "textCollection": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/TextCollection"
          }
        },
        "attachmentFolder": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/AttachmentFolder"
          },
          "description": "A folder for one or more documents in electronic form containing additional information about the freight booking confirmation.      \n"
        }
      }
    },
    "TextCreationDateTime": {
      "type": "object",
      "properties": {
        "DateTimeUTC": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "Creation date and time of the text.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalDateTime": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "Creation date and time of the text.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalTimezone": {
          "type": "string",
          "maxLength": 32,
          "example": "CET"
        }
      }
    },
    "MainCarriageActualDepartureDateTime": {
      "type": "object",
      "properties": {
        "DateTimeUTC": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "The point in time at which the carrying vehicle departed from the loading location of the main carriage stage. \nIn case of multiple main carriage stages, it refers to the first main carriage stage.\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalDateTime": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "The point in time at which the carrying vehicle departed from the loading location of the main carriage stage. \nIn case of multiple main carriage stages, it refers to the first main carriage stage.\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalTimezone": {
          "type": "string",
          "maxLength": 32,
          "example": "CET"
        }
      }
    },
    "MainCarriageActualArrivalDateTime": {
      "type": "object",
      "properties": {
        "DateTimeUTC": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "The point in time at which the carrying vehicle actually arrived at the unloading location of the main carriage stage.\nIn case of multiple main carriage stages, it refers to the last main carriage stage.\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalDateTime": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "The point in time at which the carrying vehicle actually arrived at the unloading location of the main carriage stage.\nIn case of multiple main carriage stages, it refers to the last main carriage stage.\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalTimezone": {
          "type": "string",
          "maxLength": 32,
          "example": "CET"
        }
      }
    },
    "MainCarriageWeighingDueDateTime": {
      "type": "object",
      "properties": {
        "DateTimeUTC": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "The due date time at which the weighing information of the main carriage has to be sent to the carrier party. (For VERMAS)\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalDateTime": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "The due date time at which the weighing information of the main carriage has to be sent to the carrier party. (For VERMAS)\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalTimezone": {
          "type": "string",
          "maxLength": 32,
          "example": "CET"
        }
      }
    },
    "WaybillNotificationDueDateTime": {
      "type": "object",
      "properties": {
        "DateTimeUTC": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "The document cut-off time at which the waybill notification has to be sent to the carrier party.\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalDateTime": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "The document cut-off time at which the waybill notification has to be sent to the carrier party.\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalTimezone": {
          "type": "string",
          "maxLength": 32,
          "example": "CET"
        }
      }
    },
    "ScheduledDepartureDateTime": {
      "type": "object",
      "properties": {
        "DateTimeUTC": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "The point in time at which the carrying vehicle is scheduled to depart from the loading location.\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalDateTime": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "The point in time at which the carrying vehicle is scheduled to depart from the loading location.\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalTimezone": {
          "type": "string",
          "maxLength": 32,
          "example": "CET"
        }
      }
    },
    "WeighingDueDateTime": {
      "type": "object",
      "properties": {
        "DateTimeUTC": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "The due date time at which the weighing information has to be sent to the carrier party. (For VERMAS)\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalDateTime": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "The due date time at which the weighing information has to be sent to the carrier party. (For VERMAS)\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalTimezone": {
          "type": "string",
          "maxLength": 32,
          "example": "CET"
        }
      }
    },
    "PreCarriageLatestHandOverDateTime": {
      "type": "object",
      "properties": {
        "DateTimeUTC": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "This point in time is also known as the cargo cut-off time. (Must be specified for main carriage only)\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalDateTime": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "This point in time is also known as the cargo cut-off time. (Must be specified for main carriage only)\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalTimezone": {
          "type": "string",
          "maxLength": 32,
          "example": "CET"
        }
      }
    },
    "ExpectedDepartureDateTime": {
      "type": "object",
      "properties": {
        "DateTimeUTC": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "The point in time at which the carrying vehicle is expected to depart from the loading location of a stage.\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalDateTime": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "The point in time at which the carrying vehicle is expected to depart from the loading location of a stage.\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        },
