    "OnCarriageEarliestTakeOverDateTime": {
      "type": "object",
      "properties": {
        "DateTimeUTC": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "This point in time is also known as the port pick-up time. (Must be specified for main carriage only)\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        },
        "LocalDateTime": {
          "type": "string",
          "maxLength": 24,
