{
  "swagger": "2.0",
  "info": {
    "title": "Consumer API for Freight Booking for Confirmation",
    "description": "Provides functionality for managing the freight booking process when integrating SAP Business Network for Logistics with external systems.\nThis specification describes the API from the perspective of SAP Business Network for Logistics as the consumer of the API.\nSAP Business Network for Logistics calls the defined endpoints within other systems.\n",
    "version": "1.0.16",
    "contact": {
      "name": "lbn@sap.com"
    },
    "termsOfService": ""
  },
  "x-sap-shortText": "Enables carriers to manage the freight booking process.",
  "x-servers": [
    {
      "url": "https://{host}:{port}/{basePath}",
      "description": "Test system endpoint",
      "templates": {
        "host": {
          "description": "Test system host"
        },
        "port": {
          "description": "Test system port"
        },
        "basePath": {
          "description": "Test system base path"
        }
      }
    }
  ],
  "externalDocs": {
    "description": "Click here to access detailed implementation documentation.",
    "url": "https://help.sap.com/doc/e1b2026259d84fc29e6e6760da815011/LBN/en-US/865c95c6633b43b7a3338ec5d0df237a.html"
  },
  "securityDefinitions": {
    "basicAuthentication": {
      "type": "basic"
    }
  },
  "security": [
    {
      "basicAuthentication": []
    }
  ],
  "schemes": [
    "https"
  ],
  "produces": [
    "application/json"
  ],
  "consumes": [
    "application/json"
  ],
  "tags": [
    {
      "name": "Freight Booking Request"
    }
  ],
  "paths": {
    "/FreightBookingRequest": {
      "post": {
        "summary": "Creates or updates a freight booking request",
        "tags": [
          "Freight Booking Request"
        ],
        "consumes": [
          "application/json"
        ],
        "description": "Creates/updates a freight booking request in another system.\nSAP Business Network for Logistics calls this interface when an ordering party creates/updates a freight booking request.\nThe API implementation must support `at least once` delivery.\nThe implementation must be prepared that the endpoint could be called multiple times.\n",
        "responses": {
          "201": {
            "schema": {
              "$ref": "#/definitions/ResponseStructure"
            },
            "description": "Freight booking created"
          },
          "400": {
            "description": "Bad request",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "401": {
            "description": "Unauthorized",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "403": {
            "description": "Forbidden",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "500": {
            "description": "Internal Server Error"
          }
        },
        "parameters": [
          {
            "in": "body",
            "name": "body",
            "description": "The freight booking request must be created or updated.",
            "required": true,
            "schema": {
              "$ref": "#/definitions/PostFreightBookingForSubcontracting"
            }
          }
        ]
      }
    },
    "/FreightBookingRequestCancellation": {
      "post": {
        "summary": "Cancels a freight booking request",
        "tags": [
          "Freight Booking Cancellation"
        ],
        "consumes": [
          "application/json"
        ],
        "description": "Cancels a freight booking request in an external system.\nSAP Business Network for Logistics calls this interface when an ordering party cancels a freight booking request.\nThe API implementation must support `at least once` delivery.\nThe implementation must be prepared that the endpoint could be called multiple times.\n",
        "parameters": [
          {
            "in": "body",
            "name": "body",
            "description": "The freight booking request must be canceled.",
            "required": true,
            "schema": {
              "$ref": "#/definitions/PostFreightBookingForSubcontractingCancellation"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Freight booking request cancelled",
            "schema": {
              "$ref": "#/definitions/ResponseStructure"
            }
          },
          "400": {
            "description": "Bad request",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "401": {
            "description": "Unauthorized",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "403": {
            "description": "Forbidden",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "404": {
            "description": "Not found",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "500": {
            "description": "Internal server error"
          }
        }
      }
    },
    "/FreightBookingWaybillNotification": {
      "post": {
        "summary": "Creates or updates a freight booking waybill information",
        "tags": [
          "Freight Booking Waybill Notification"
        ],
        "consumes": [
          "application/json"
        ],
        "description": "Creates or updates a freight booking waybill information in external systems.\nSAP Business Network for Logistics calls this interface when an ordering party creates or updates a freight booking waybill notification.\nThe API implementation must support at least once delivery.\nThe implementation must be prepared that the endpoint could be called multiple times.\n",
        "responses": {
          "201": {
            "schema": {
              "$ref": "#/definitions/ResponseStructure"
            },
            "description": "Freight booking waybill created"
          },
          "400": {
            "description": "Bad request",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "401": {
            "description": "Unauthorized",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "403": {
            "description": "Forbidden",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "500": {
            "description": "Internal Server Error"
          }
        },
        "parameters": [
          {
            "in": "body",
            "name": "body",
            "description": "The freight booking waybill notification must be created or updated.",
            "required": true,
            "schema": {
              "$ref": "#/definitions/PostFreightBookingWayBillNotification"
            }
          }
        ]
      }
    }
  },
