          "Freight Orders for Subcontracting"
        ],
        "description": "Creates a carrier response for a freight order for subcontracting in SAP Business Network for Logistics.\nWith this functionality, a carrier can confirm or reject a freight order for subcontracting.\nWhen confirming, an alternative price can be proposed, if permitted by the ordering party.\nThe alternative price is the amount for which the carrier agrees to execute the transportation.\nIn addition, driver names and details about the vehicle can be provided.\nWhen rejecting, a reason code can be provided.\n",
        "consumes": [
          "application/json"
        ],
        "produces": [
          "application/json"
        ],
        "parameters": [
          {
            "name": "orderingPartyLbnId",
            "in": "path",
            "description": "Identifier of the ordering party within SAP Business Network for Logistics.\n",
            "required": true,
            "type": "string"
          },
          {
            "name": "originatorId",
            "in": "path",
            "description": "Identifier of the originating system of the ordering party.\n",
            "required": true,
            "type": "string"
          },
          {
            "name": "freightOrderId",
            "in": "path",
            "description": "Identifier of the freight order for subcontracting.\n",
            "required": true,
            "type": "string"
          },
          {
            "in": "body",
            "name": "body",
            "description": "Carrier response to a freight order for subcontracting.",
            "required": true,
            "schema": {
              "$ref": "#/definitions/PostFreightOrderForSubcontractingCarrierResponse"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "OK"
          },
          "400": {
            "description": "Bad Request",
            "examples": {
              "application/json": {
                "message": "Price proposal can not be changed for freight order [ID: 6100034059, Originator ID: XYZ_123, Ordering Party LBN ID: 10000042]"
              }
            },
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "401": {
            "description": "Unauthorized"
          },
          "403": {
            "description": "Forbidden"
          },
          "404": {
            "description": "Not Found",
            "examples": {
              "application/json": {
                "message": "Freight order [ID: 6100034059, Originator ID: XYZ_123, Ordering Party LBN ID: 10000042] could not be found"
              }
            },
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "412": {
            "description": "Precondition Failed",
            "examples": {
              "application/json": {
                "message": "Relationship of Ordering Party (shipper) LBN Id: 10000042 and Carrier Party LBN Id: 10000043 has not yet been established"
              }
            },
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "500": {
            "description": "Internal server error",
            "examples": {
              "application/json": {
                "message": "An internal server error occurred"
              }
            },
            "schema": {
              "$ref": "#/definitions/Error"
            }
          }
        }
      }
    }
  },
  "securityDefinitions": {
    "eu10": {
      "type": "oauth2",
      "description": "To use the EU10 data center API, you must obtain the OAuth client credentials (client ID and secret). \nTo get the OAuth client credentials, create a customer incident on SAP support portal with the component as SBN-LBN-INT. \nProvide the SAP Business Network for Logistics ID created for your account and the email address to receive your client credentials. \nSpecify the target integration platform as ‘Multi-Cloud (new)’ and the title as ‘SAP BN4L Integration Platform Migration: Request for new OAuth 2.0 credential’. \nOnce you receive the credentials, pass the details to SAP HANA Cloud Platform token endpoint to obtain an access token.\n",
      "tokenUrl": "https://bn4lintegrationsuiteliveeu10-d2q5jmpt.authentication.eu10.hana.ondemand.com/oauth/token?grant_type=client_credentials",
      "flow": "application",
      "scopes": {
        "{identityzone}.custom-activity_view": "Get custom activity step information.",
        "{identityzone}.custom-activity_confirm": "Confirm custom activity step information retrieval."
      }
    },
    "us20": {
      "type": "oauth2",
      "description": "To use the US20 data center API, you must obtain the OAuth client credentials (client ID and secret). \nTo get the OAuth client credentials, create a customer incident on SAP support portal with the component as SBN-LBN-INT. \nProvide the SAP Business Network for Logistics ID created for your account and the email address to receive your client credentials. \nSpecify the target integration platform as ‘Multi-Cloud (new)’ and the title as ‘SAP BN4L Integration Platform Migration: Request for new OAuth 2.0 credential’. \nOnce you receive the credentials, pass the details to SAP HANA Cloud Platform token endpoint to obtain an access token.\n",
      "tokenUrl": "https://bn4lintegrationsuiteliveus20-0gohdecj.authentication.us20.hana.ondemand.com/oauth/token?grant_type=client_credentials",
      "flow": "application",
      "scopes": {
        "{identityzone}.custom-activity_view": "Get custom activity step information.",
        "{identityzone}.custom-activity_confirm": "Confirm custom activity step information retrieval."
      }
    }
  },
  "definitions": {
    "PostFreightOrderForSubcontractingCarrierResponse": {
      "type": "object",
      "required": [
        "carrierPartyLbnId",
        "confirmationStatus"
      ],
      "properties": {
        "carrierPartyLbnId": {
          "$ref": "#/definitions/CarrierPartyLbnId"
        },
        "confirmationStatus": {
          "type": "string",
          "maxLength": 2,
          "enum": [
            "CN",
            "RE"
          ],
          "description": "Confirm or reject freight order for subcontracting.\n* CN - Confirm freight order for subcontracting\n* RE - Reject freight order for subcontracting\n"
        },
        "networkPartner": {
          "$ref": "#/definitions/NetworkPartner"
        },
        "driver1Name": {
          "type": "string",
          "description": "Name of driver assigned to truck (two drivers can be assigned).\nIt is not supported for consignment orders.\n",
          "maxLength": 40
        },
        "driver2Name": {
          "type": "string",
          "description": "Name of driver assigned to truck (two drivers can be assigned).\nIt is not supported for consignment orders.\n",
          "maxLength": 40
        },
        "trailerID": {
          "type": "string",
          "description": "Identifier of the trailer that will execute the order. \nIt is not supported for consignment orders.\n",
          "maxLength": 25
        },
        "truckID": {
          "type": "string",
          "description": "Identifier of the truck that will execute the order. \nIt is not supported for consignment orders.\n",
          "maxLength": 25
        },
        "driver1AddDetails": {
          "$ref": "#/definitions/DriverAddDetails"
        },
        "driver2AddDetails": {
          "$ref": "#/definitions/DriverAddDetails"
        },
        "transportMeansID": {
          "type": "string",
          "description": "Vehicle license plate of the truck that will execute the order.\nIt is not supported for consignment orders.\n",
          "maxLength": 35
        },
        "transportMeansHomeCountryCode": {
          "type": "string",
          "example": "DE",
          "description": "Country code of vehicle license plate, specified in ISO 3166-1 alpha-2 – two-character country code format.\nIt is not supported for consignment orders.\n",
          "maxLength": 3
        },
        "rejectionReasonCode": {
          "type": "string",
          "example": "LBN_CAPA",
          "description": "The reason (code) selected by the carrier to explain why they rejected the freight order for subcontracting.\nShould be used together with `confirmationStatus` when confirmation status `RE` is provided.\n* LBN_CAPA - No capacity\n* LBN_OTHERS - Other\n* LBN_PRICE - Price\n* LBN_TIME - No time\n",
          "maxLength": 10,
          "enum": [
            "LBN_CAPA",
            "LBN_OTHERS",
            "LBN_PRICE",
            "LBN_TIME"
          ]
        },
        "proposalPrice": {
          "$ref": "#/definitions/PostFreightOrderForSubcontractingCarrierResponse_proposalPrice"
        },
        "note": {
          "$ref": "#/definitions/PostFreightOrderForSubcontractingCarrierResponse_note"
        },
        "attachments": {
          "type": "array",
          "description": "Attachments can be provided by the carrier in Base 64 encoded format\n",
          "items": {
            "$ref": "#/definitions/Attachment"
          }
        },
        "cargoItems": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/Item"
          }
        },
        "businessDocumentReferences": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/BusinessDocumentReference"
          },
          "description": "A unique reference to other business documents that are of significance within each respective business process.\n"
        }
      }
    },
    "CarrierPartyLbnId": {
      "type": "string",
      "maxLength": 40,
      "description": "Identifier of the carrier within SAP Business Network for Logistics.\n",
      "example": "10000043"
    },
    "NetworkPartner": {
      "type": "object",
      "properties": {
        "networkPartnerLBNID": {
          "type": "string",
          "example": "10000042",
          "description": "Identifier of the network partner within SAP Business Network for Logistics.\n",
          "maxLength": 35
        }
      }
    },
    "DriverAddDetails": {
      "type": "object",
      "properties": {
        "communication": {
          "type": "object",
          "properties": {
            "mobilePhone": {
              "type": "object",
              "properties": {
                "number": {
                  "type": "object",
                  "properties": {
                    "areaID": {
                      "type": "string",
                      "description": "The area code associated with the mobile phone number.\nIt is not supported for consignment orders.\n",
                      "maxLength": 10
                    },
                    "subscriberID": {
                      "type": "string",
                      "description": "The mobile phone number of the assigned driver.\nIt is not supported for consignment orders.\n",
                      "maxLength": 30
                    },
                    "countryDiallingCode": {
                      "type": "string",
                      "description": "The country code associated with the mobile phone number. \nIt is not supported for consignment orders.\n",
                      "maxLength": 10
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "Error": {
      "type": "object",
      "required": [
        "message"
      ],
      "properties": {
        "message": {
          "type": "string",
          "example": "Some error message",
          "description": "Error message\n"
        }
      }
    },
    "PostFreightOrderForSubcontractingCarrierResponse_proposalPrice": {
      "properties": {
        "value": {
          "type": "number",
          "example": 1500,
          "description": "Amount that the carrier proposes for executing a freight order for subcontracting.\n",
          "x-precision": 28,
          "x-scale": 6
        },
        "currency": {
          "type": "string",
          "example": "USD",
          "description": "Format must be compliant with SAP Global Data Type `CurrencyCode` (`listID` = `4217`, `listAgencyID` = `5`). [Codelist](https://help.sap.com/docs/SAP_LBN_FC_OPTION/40f43410e8a64dc98792a5e610e81017/c5ff86c3b2c744b4aab2ade9d9b1f05e.html)\n",
          "maxLength": 3
        }
      },
      "description": "Amount that the carrier proposes for executing a freight order for subcontracting.\nPrice proposal can be used to propose an alternative price in case property `priceIsNegotiable` is `true`.\nPrice proposal is considered only if the freight order for subcontracting is confirmed (`confirmationStatus` = `CN`).\nIn other cases it is ignored.\n"
    },
    "PostFreightOrderForSubcontractingCarrierResponse_note": {
      "properties": {
        "text": {
          "type": "string",
          "description": "Natural-language text with additional information about the freight order for subcontracting.\nThe note is language-independent.\n",
          "maxLength": 3000
        }
      }
    },
    "Item": {
      "type": "object",
      "properties": {
        "ItemId": {
          "type": "string",
          "maxLength": 100,
          "description": "Identifier of a cargo item.\n",
          "example": "10"
        },
        "containerId": {
          "type": "string",
          "description": "Identifier of the container that will be used by the ordering party for tracking purposes.\n",
          "maxLength": 60
        }
      }
    },
    "Attachment": {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "description": "Name of the attachment along with the file extension.\n",
          "maxLength": 255,
          "example": "Document.pdf"
        },
        "mimeCode": {
          "type": "string",
          "description": "Content type code of the attachment.\n* image/jpeg - Mime code for image files with .jpeg extension\n* image/jpg - Mime code for image files with .jpg extension\n* image/png - Mime code for image files with .png extension\n* image/gif - Mime code for image files with .gif extension\n* image/tiff - Mime code for image files with .tiff extension\n* image/tiff-fx - Mime code for image files with .tiff-fx extension\n* application/pdf - Mime code for files with .pdf extension\n* application/msword - Mime code for files with .doc extension\n* application/vnd.openxmlformats-officedocument.wordprocessingml.document - Mime code for files with .docx extension\n* application/vnd.ms-excel - Mime code for files with .xls extension\n* application/vnd.openxmlformats-officedocument.spreadsheetml.sheet - Mime code for files with .xlsx extension\n",
          "maxLength": 255,
          "enum": [
            "image/jpeg",
            "image/jpg",
            "image/png",
            "image/gif",
            "image/tiff",
            "image/tiff-fx",
            "application/pdf",
            "application/msword",
            "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            "application/vnd.ms-excel",
            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
          ],
          "example": "application/pdf"
        },
        "fileContentBinaryObject": {
          "type": "string",
          "format": "byte",
          "description": "Attachment Content in Base 64 encoded format.\n"
        }
      }
    },
    "BusinessDocumentReference": {
      "type": "object",
      "properties": {
        "documentId": {
          "type": "string",
          "maxLength": 35,
          "description": "An identifier for a referenced business document.\n"
        },
        "documentTypeCode": {
          "type": "string",
          "maxLength": 6,
          "description": "A coded representation of the type of business document that is referenced. [Codelist](https://help.sap.com/docs/SAP_LBN_FC_OPTION/40f43410e8a64dc98792a5e610e81017/0bdcb1463bbf4f628d9513e6e223ab7a.html)\n",
          "example": "1122"
        },
        "documentDateTime": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "description": "The date on which a referenced business document or business document item was created.\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "example": "2018-12-31T23:59:00Z"
        }
      }
    }
  },
  "x-sap-shortText": "Enables carriers to manage the freight orders for subcontracting process.",
  "x-servers": [
    {
      "url": "https://api.logistics.eu.business-network.cloud.sap/http/v1",
      "description": "FreightOrderForSubcontracting API endpoint for EU10 data center"
    },
    {
      "url": "https://api.logistics.us.business-network.cloud.sap/http/v1",
      "description": "FreightOrderForSubcontracting API endpoint for US20 data center"
    }
  ]
}

