{
  "swagger": "2.0",
  "info": {
    "title": "Consumer API for Freight Tendering",
    "description": "Provides functionality for managing freight requests for quotation and freight quotations as part of the freight tendering process when integrating SAP Business Network for Logistics with other systems.\nThis specification describes the API from the viewpoint of SAP Business Network for Logistics as the consumer of API.\nSAP Business Network for Logistics calls the defined endpoints within other systems.\n",
    "version": "1.0.18",
    "contact": {
      "name": "lbn@sap.com"
    },
    "termsOfService": ""
  },
  "x-sap-shortText": "Enables carriers to manage freight requests for quotation and freight quotations as part of the freight tendering process.",
  "x-servers": [
    {
      "url": "https://{host}:{port}/{basePath}",
      "description": "Test system endpoint",
      "templates": {
        "host": {
          "description": "Test system host"
        },
        "port": {
          "description": "Test system port"
        },
        "basePath": {
          "description": "Test system base path"
        }
      }
    }
  ],
  "externalDocs": {
    "description": "Click here to access detailed implementation documentation.",
    "url": "https://help.sap.com/doc/e1b2026259d84fc29e6e6760da815011/LBN/en-US/69cdfd485e8d4e2fa82178405e4778ee.html"
  },
  "securityDefinitions": {
    "basicAuthentication": {
      "type": "basic"
    }
  },
  "security": [
    {
      "basicAuthentication": []
    }
  ],
  "schemes": [
    "https"
  ],
  "produces": [
    "application/json"
  ],
  "consumes": [
    "application/json"
  ],
  "tags": [
    {
      "name": "Freight Requests for Quotation"
    },
    {
      "name": "Freight Quotations"
    }
  ],
  "paths": {
    "/LbnFreightRequestForQuotation": {
      "post": {
        "tags": [
          "Freight Requests for Quotation"
        ],
        "summary": "Creates a freight request for quotation in another system.",
        "description": "This interface is called by SAP Business Network for Logistics when an ordering party creates a freight request for quotation.\nThe API implementation must support `at least once` delivery.\nThe implementation must be prepared that the endpoint could be called multiple times.\n",
        "consumes": [
          "application/json"
        ],
        "parameters": [
          {
            "in": "body",
            "name": "body",
            "description": "Freight request for quotation to be created.",
            "required": true,
            "schema": {
              "$ref": "#/definitions/PostFreightRequestForQuotation"
            }
          }
        ],
        "responses": {
          "201": {
            "description": "Freight request for quotation created successfully.",
            "schema": {
              "type": "object",
              "properties": {
                "freightRequestForQuotationId": {
                  "$ref": "#/definitions/FreightRequestForQuotationId"
                }
              }
            }
          },
          "400": {
            "description": "Bad Request",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "401": {
            "description": "Unauthorized"
          },
          "403": {
            "description": "Forbidden"
          },
          "412": {
            "description": "Precondition Failed",
            "examples": {
              "application/json": {
                "message": "Relationship betweeen the ordering party (ID: 10000042) and the carrier (ID: 10000043) has not yet been established."
              }
            },
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "500": {
            "description": "Internal Server Error",
            "schema": {
              "$ref": "#/definitions/500"
            }
          }
        }
      }
    },
    "/LbnFreightRequestForQuotation/{orderingPartyLbnId}/{originatorId}/{freightRequestForQuotationId}/cancellation": {
      "post": {
        "tags": [
          "Freight Requests for Quotation"
        ],
        "summary": "Cancels a freight request for quotation in another system.",
        "description": "This interface is called by SAP Business Network for Logistics when an ordering party cancels a freight request for quotation.\nThe API implementation must support `at least once` delivery.\nThe implementation must be prepared that the endpoint could be called multiple times.\n",
        "consumes": [
          "application/json"
        ],
        "parameters": [
          {
            "name": "orderingPartyLbnId",
            "in": "path",
            "description": "Identifier of the ordering party within SAP Business Network for Logistics.\n",
            "required": true,
            "type": "string"
          },
          {
            "name": "originatorId",
            "in": "path",
            "description": "Identifier of the ordering party's originating system.\n",
            "required": true,
            "type": "string"
          },
          {
            "name": "freightRequestForQuotationId",
            "in": "path",
            "description": "Identifier of the freight request for quotation.\n",
            "required": true,
            "type": "string"
          },
          {
            "in": "body",
            "name": "body",
            "description": "Freight request for quotation to be canceled.",
            "required": true,
            "schema": {
              "$ref": "#/definitions/PostFreightRequestForQuotationCancellation"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Freight request for quotation canceled successfully.",
            "schema": {
              "type": "object",
              "properties": {
                "freightRequestForQuotationId": {
                  "$ref": "#/definitions/FreightRequestForQuotationId"
                }
              }
            }
          },
          "400": {
            "description": "Bad Request",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "401": {
            "description": "Unauthorized"
          },
          "403": {
            "description": "Forbidden"
          },
          "404": {
            "description": "Not Found",
            "examples": {
              "application/json": {
                "message": "Freight request for quotation [ID: 6100034059, Originator ID: XYZ_123, Ordering Party LBN ID: 10000042] could not be found"
              }
            },
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "412": {
            "description": "Precondition Failed",
            "examples": {
              "application/json": {
                "message": "Relationship of Ordering Party (shipper) LBN Id: 10000042 and Carrier Party LBN Id: 10000043 has not yet been established"
              }
            },
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "500": {
            "description": "Internal Server Error",
            "schema": {
              "$ref": "#/definitions/500"
            }
          }
        }
      }
    },
    "/LbnFreightQuotation/{orderingPartyLbnId}/{originatorId}/{freightQuotationId}/notification": {
      "post": {
        "tags": [
          "Freight Quotations"
        ],
        "summary": "Awards or rejects a freight quotation in another system.",
        "description": "This interface is called by SAP Business Network for Logistics when an ordering party awards or rejects a freight quotation.\nThe API implementation must support `at least once` delivery.\nThe implementation must be prepared that the endpoint could be called multiple times.\n",
        "parameters": [
          {
            "name": "orderingPartyLbnId",
            "in": "path",
            "description": "Identifier of the ordering party within SAP Business Network for Logistics.\n",
            "required": true,
            "type": "string"
          },
          {
            "name": "originatorId",
            "in": "path",
            "description": "Identifier of the originating system of the ordering party.\n",
            "required": true,
            "type": "string"
          },
          {
            "name": "freightQuotationId",
            "in": "path",
            "description": "Identifier of the freight quotation\n",
            "required": true,
            "type": "string"
          },
          {
            "in": "body",
            "name": "body",
            "description": "Freight quotation to be awarded or rejected.",
            "required": true,
            "schema": {
              "$ref": "#/definitions/PostFreightQuotationNotification"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Freight quotation awarded or rejected successfully.",
            "schema": {
              "type": "object",
              "properties": {
                "freightQuotationId": {
                  "$ref": "#/definitions/CompositeFreightQuotationId"
                }
              }
            }
          },
          "401": {
            "description": "Unauthorized"
          },
          "403": {
            "description": "Forbidden"
          },
          "404": {
            "description": "Not Found",
            "examples": {
              "application/json": {
                "message": "Freight request for quotation [ID: 6100034059, Originator ID: XYZ_123, Ordering Party LBN ID: 10000042] could not be found"
              }
            },
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "412": {
            "description": "Precondition Failed",
            "examples": {
              "application/json": {
                "message": "Relationship of Ordering Party (shipper) LBN Id: 10000042 and Carrier Party LBN Id: 10000043 has not yet been established"
              }
            },
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "500": {
            "description": "Internal Server Error",
            "schema": {
              "$ref": "#/definitions/500"
            }
          }
        }
      }
    }
  },
  "definitions": {
    "500": {
      "description": "Internal server error"
    },
    "PostFreightRequestForQuotation": {
      "type": "object",
      "required": [
        "carrierPartyLbnId",
        "freightRequestForQuotationId",
        "orderingPartyLbnId",
        "originatorId"
      ],
      "properties": {
        "freightRequestForQuotationId": {
          "$ref": "#/definitions/FreightRequestForQuotationId"
        },
        "orderingPartyLbnId": {
          "$ref": "#/definitions/OrderingPartyLbnId"
        },
        "carrierPartyLbnId": {
          "$ref": "#/definitions/CarrierPartyLbnId"
        },
        "originatorId": {
          "$ref": "#/definitions/OriginatorId"
