          "$ref": "#/definitions/Item_grossVolume"
        },
        "pieces": {
          "$ref": "#/definitions/Item_pieces"
        },
        "length": {
          "$ref": "#/definitions/Item_length"
        },
        "width": {
          "$ref": "#/definitions/Item_width"
        },
        "height": {
          "$ref": "#/definitions/Item_height"
        },
        "temperatureRequirement": {
          "$ref": "#/definitions/Item_temperatureRequirement"
        },
        "stackable": {
          "type": "boolean",
          "default": false
        },
        "highValue": {
          "type": "boolean",
          "default": false
        },
        "oversize": {
          "type": "boolean",
          "default": false
        },
        "transportationCommodityClassifications": {
          "$ref": "#/definitions/TransportationCommodityClassifications"
        },
        "shipFromLocationId": {
          "type": "string",
          "description": "An identifier in the originating system of the ship-from location involved in the transportation chain represented by a freight request for quotation, also known as source location.\n",
          "maxLength": 20
        },
        "shipToLocationId": {
          "type": "string",
          "description": "An identifier in the originating system of the ship-to location involved in the transportation chain represented by a freight request for quotation, also known as destination location.\n",
          "maxLength": 20
        },
        "dangerousGoodsInfo": {
          "type": "array",
          "description": "Information about items that are specified as dangerous goods.\n",
          "items": {
            "$ref": "#/definitions/DangerousGoodsInfo"
          }
        },
        "equipmentType": {
          "type": "string",
          "description": "An identifier for the type of equipment. [Codelist](https://help.sap.com/docs/SAP_LBN_FC_OPTION/40f43410e8a64dc98792a5e610e81017/7f9d079030644e138e3ddfc2b97edd1f.html)\n",
          "maxLength": 10
        },
        "equipmentGroup": {
          "type": "string",
          "description": "An identifier for the equipment group.\n",
          "maxLength": 10
        }
      },
      "description": "Detailed information about the goods to be transported.\n"
    },
    "BusinessDocumentReference": {
      "type": "object",
      "properties": {
        "id": {
          "type": "string",
          "description": "An identifier for a referenced business document.\n",
          "maxLength": 35
        },
        "typeCode": {
          "type": "string",
          "description": "A coded representation of the type of business document that is referenced. [Codelist](https://help.sap.com/docs/SAP_LBN_FC_OPTION/40f43410e8a64dc98792a5e610e81017/0bdcb1463bbf4f628d9513e6e223ab7a.html)\n",
          "maxLength": 5
        },
        "dateTime": {
          "type": "string",
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "example": "2018-12-31T23:59:00Z",
          "description": "The date on which a referenced business document or business document item was created.\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "maxLength": 24
        },
        "version": {
          "type": "string",
          "description": "An identifier for a version of a referenced business document or business document item.\n",
          "maxLength": 32
        },
        "itemId": {
          "type": "string",
          "description": "An identifier for the referenced business document item.\n",
          "maxLength": 10
        },
        "itemTypeCode": {
          "type": "string",
          "description": "A coded representation of the type of business document item that is referenced. [Codelist](https://help.sap.com/docs/SAP_LBN_FC_OPTION/40f43410e8a64dc98792a5e610e81017/072f8ca8634147a7beb4770e3cd94d6b.html)\n",
          "maxLength": 5
        }
      }
    },
    "CategoryCode": {
      "type": "string",
      "maxLength": 3,
      "description": "A coded representation of the category of an item.\n* PRD - Product\n* PKG - Package\n* TUR - Container\n[Codelist](https://help.sap.com/docs/SAP_LBN_FC_OPTION/40f43410e8a64dc98792a5e610e81017/cd95fadc6e814573aaeccbedb91e5920.html)\n",
      "example": "PKG",
      "enum": [
        "PKG",
        "PRD",
        "TUR"
      ]
    },
    "DangerousGoodsInfo": {
      "type": "object",
      "required": [
        "dangerousGoodsId"
      ],
      "properties": {
        "dangerousGoodsId": {
          "type": "string",
          "description": "Dangerous Goods ID",
          "maxLength": 4
        },
        "regulationsCode": {
          "type": "string",
          "description": "Dangerous Goods Regulations Code",
          "maxLength": 3
        },
        "classId": {
          "type": "string",
          "description": "Dangerous Goods Class Id",
          "maxLength": 3
        },
        "identifierTypeCode": {
          "type": "string",
          "description": "Identifier Type Code",
          "maxLength": 3
        },
        "packingGroupCode": {
          "type": "string",
          "description": "Packing Group Code",
          "maxLength": 1
        },
        "dangerousGoodsTexts": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/DangerousGoodsText"
          }
        }
      }
    },
    "PackageTypeCode": {
      "type": "string",
      "maxLength": 17,
      "description": "Coded representation of a package type.\n"
    },
    "SpecialHandlingCode": {
      "type": "string",
      "maxLength": 3,
      "description": "A coded representation of a special handling instruction that must be followed for transportation. [Codelist](https://help.sap.com/docs/SAP_LBN_FC_OPTION/40f43410e8a64dc98792a5e610e81017/2e6d6cec52004a6294b802f1804b3791.html)\n"
    },
    "TransportationCommodityClassifications": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/TransportationCommodityClassification"
      }
    },
    "TransportModeCode": {
      "type": "string",
      "maxLength": 2,
      "description": "A coded representation for the mode of transport used for transportation, as per the EDIFACT codelist 8067.\n* 1  | Ocean Transport\n     Transport of goods and/or persons by ocean\n* 3  | Road Transport\n     Transport of goods and/or persons by road\n* 4  | Air transport\n     Transport of goods and/or persons by air\n"
    },
    "LbnTransportationModeCode": {
      "type": "string",
      "maxLength": 2,
      "description": "A coded representation of the transportation mode. [codelist](https://help.sap.com/docs/business-network-freight-collaboration/code-lists/transportation-modes)\n* 01  | Ocean Transport\n      Transport of goods and/or persons by ocean\n* 03  | Road Transport\n      Transport of goods and/or persons by road\n* 04  | Air transport\n      Transport of goods and/or persons by air\n"

file://api-specs/FreightTendering_Provid.content:
{
  "swagger": "2.0",
  "info": {
    "description": "Provides functionality for managing freight requests for quotation, including the created freight quotations, as part of the freight tendering process when integrating SAP Business Network for Logistics with other systems.\nThis specification describes the API from the perspective of SAP Business Network for Logistics as the provider of the API.\nOther systems call the defined endpoints within SAP Business Network for Logistics.\n",
    "version": "1.0.7",
    "title": "Provider API for Freight Tendering",
    "termsOfService": "",
    "contact": {
      "name": "lbn@sap.com"
    }
  },
  "externalDocs": {
    "description": "Click here to access detailed implementation documentation.",
    "url": "https://help.sap.com/doc/e1b2026259d84fc29e6e6760da815011/LBN/en-US/438389cfaf5f43678f878b0ecb280235.html"
  },
  "tags": [
    {
      "name": "Freight Quotations"
    }
  ],
  "schemes": [
    "https"
  ],
  "consumes": [
    "application/json"
  ],
  "produces": [
    "application/json"
  ],
  "security": [
    {
      "eu10": [
        "{identityzone}.custom-activity_view",
        "{identityzone}.custom-activity_confirm"
      ]
    },
    {
      "us20": [
        "{identityzone}.custom-activity_view",
        "{identityzone}.custom-activity_confirm"
      ]
    }
  ],
  "paths": {
    "/LbnFreightQuotation": {
      "post": {
        "summary": "Creates a freight quotation for a freight request for quotation",
        "tags": [
          "Freight Quotations"
        ],
        "description": "Creates a freight quotation for a freight request for quotation in SAP Business Network for Logistics.\nWith this functionality, a carrier can accept or reject a freight request for quotation.\nWhen accepting, an alternative price can be proposed if permitted by the ordering party.\nThe alternative price is the amount for which the carrier agrees to execute the transportation.\nWhen accepting, alternative loading and unloading times for transportation stages can be proposed, if permitted by the ordering party.\nThe alternative times are the points in time for which the carrier agrees to accept the freight request for quotation.\nWhen rejecting, a reason code can be provided.\n",
        "consumes": [
          "application/json"
        ],
        "produces": [
          "application/json"
        ],
        "parameters": [
          {
            "in": "body",
            "name": "body",
            "description": "Freight request for quotation to be accepted or rejected.",
            "required": true,
            "schema": {
              "$ref": "#/definitions/PostFreightQuotation"
            }
          }
        ],
        "responses": {
          "201": {
            "description": "Created",
            "schema": {
              "type": "object",
              "properties": {
                "freightQuotationId": {
                  "$ref": "#/definitions/CompositeFreightQuotationId"
                }
              }
            }
          },
          "400": {
            "description": "Bad Request",
            "examples": {
              "application/json": {
                "message": "RFQ [ID: 5100003410, Originator ID: XYZ_123, Ordering Party LBN ID: 10000042] is no longer open"
              }
            },
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "401": {
            "description": "Unauthorized"
          },
          "403": {
            "description": "Forbidden"
          },
          "404": {
            "description": "Not Found",
            "examples": {
              "application/json": {
                "message": "Request for Quotation [ID: 5100003410, Originator ID: XYZ_123, Ordering Party LBN ID: 10000042] could not be found"
              }
            },
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "412": {
            "description": "Precondition Failed",
            "examples": {
              "application/json": {
                "message": "Relationship of Ordering Party (shipper) LBN Id: 10000042 and Carrier Party LBN Id: 10000043 has not yet been established"
              }
            },
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "500": {
            "description": "Internal server error",
            "examples": {
              "application/json": {
                "message": "An internal server error occurred"
              }
            },
            "schema": {
              "$ref": "#/definitions/Error"
            }
          }
        }
      }
    }
  },
  "securityDefinitions": {
    "eu10": {
      "type": "oauth2",
      "description": "To use the EU10 data center API, you must obtain the OAuth client credentials (client ID and secret). \nTo get the OAuth client credentials, create a customer incident on SAP support portal with the component as SBN-LBN-INT. \nProvide the SAP Business Network for Logistics ID created for your account and the email address to receive your client credentials. \nSpecify the target integration platform as ‘Multi-Cloud (new)’ and the title as ‘SAP BN4L Integration Platform Migration: Request for new OAuth 2.0 credential’. \nOnce you receive the credentials, pass the details to SAP HANA Cloud Platform token endpoint to obtain an access token.\n",
      "tokenUrl": "https://bn4lintegrationsuiteliveeu10-d2q5jmpt.authentication.eu10.hana.ondemand.com/oauth/token?grant_type=client_credentials",
      "flow": "application",
      "scopes": {
        "{identityzone}.custom-activity_view": "Get custom activity step information.",
        "{identityzone}.custom-activity_confirm": "Confirm custom activity step information retrieval."
      }
    },
    "us20": {
      "type": "oauth2",
      "description": "To use the US20 data center API, you must obtain the OAuth client credentials (client ID and secret). \n To get the OAuth client credentials, create a customer incident on SAP support portal with the component as SBN-LBN-INT. \n Provide the SAP Business Network for Logistics ID created for your account and the email address to receive your client credentials. \n Specify the target integration platform as ‘Multi-Cloud (new)’ and the title as ‘SAP BN4L Integration Platform Migration: Request for new OAuth 2.0 credential’. \n Once you receive the credentials, pass the details to SAP HANA Cloud Platform token endpoint to obtain an access token.\n",
      "tokenUrl": "https://bn4lintegrationsuiteliveus20-0gohdecj.authentication.us20.hana.ondemand.com/oauth/token?grant_type=client_credentials",
      "flow": "application",
      "scopes": {
        "{identityzone}.custom-activity_view": "Get custom activity step information.",
        "{identityzone}.custom-activity_confirm": "Confirm custom activity step information retrieval."
      }
    }
  },
  "definitions": {
    "PostFreightQuotation": {
      "type": "object",
      "required": [
        "carrierPartyLbnId",
        "freightRequestForQuotationId",
        "orderingPartyLbnId",
        "originatorId",
        "responseCode"
      ],
      "properties": {
        "freightRequestForQuotationId": {
          "$ref": "#/definitions/FreightRequestForQuotationId"
        },
        "freightQuotationId": {
          "$ref": "#/definitions/ExternalFreightQuotationId"
        },
        "orderingPartyLbnId": {
          "$ref": "#/definitions/OrderingPartyLbnId"
        },
        "carrierPartyLbnId": {
          "$ref": "#/definitions/CarrierPartyLbnId"
        },
        "originatorId": {
          "$ref": "#/definitions/OriginatorId"
        },
        "networkPartner": {
          "$ref": "#/definitions/NetworkPartner"
        },
        "responseCode": {
          "type": "string",
          "example": "AP",
          "description": "The response to the freight request for quotation.\nThe freight request for quotation can be accepted or rejected.\n* AP - Accept the freight request for quotation\n* RE - Reject the freight request for quotation\n",
          "maxLength": 2,
          "enum": [
            "AP",
            "RE"
          ]
        },
        "rejectionReasonCode": {
          "type": "string",
          "example": "LBN_CAPA",
          "description": "The reason (code) selected by the carrier to explain why they rejected the freight request for quotation.\nShould be used together with `responseCode` when response code `RE` is provided.\n* LBN_CAPA - No capacity\n* LBN_OTHERS - Other\n* LBN_PRICE - Price\n* LBN_TIME - No time\n",
          "maxLength": 10,
          "enum": [
            "LBN_CAPA",
            "LBN_OTHERS",
            "LBN_PRICE",
            "LBN_TIME"
          ]
        },
        "proposalPrice": {
          "$ref": "#/definitions/PostFreightQuotation_proposalPrice"
        },
        "transportationStages": {
          "type": "array",
          "description": "Information about a section of the transportation chain represented by a freight request for quotation.\nTransportation stages can be used to propose different loading and unloading times if the property `datesAreNegotiable` for the referenced freight request for quotation is `true`.\nThe alternative times are the times for which the carrier agrees to execute a freight request for quotation.\nTransportation stages are considered only if the freight request for quotation is accepted (`responseCode` = `AP`).\nIn other cases, it is ignored.\n",
          "items": {
            "$ref": "#/definitions/TransportationStageItemPostFreightQuotation"
          }
        },
        "note": {
          "$ref": "#/definitions/PostFreightQuotation_note"
        },
        "attachments": {
          "type": "array",
          "description": "Attachments can be provided by the carrier in Base 64 encoded format\n",
          "items": {
            "$ref": "#/definitions/Attachment"
          }
        }
      }
    },
    "FreightRequestForQuotationId": {
      "type": "string",
      "maxLength": 35,
      "description": "Identifier of the freight request for quotation.\n",
      "example": "5100003410"
    },
    "ExternalFreightQuotationId": {
      "type": "string",
      "maxLength": 35,
      "pattern": "^[A-Z0-9]*$",
      "description": "Identifier of the freight quotation from carrier's perspective.\n",
      "example": 5100003410
    },
    "CompositeFreightQuotationId": {
      "type": "string",
      "maxLength": 40,
      "description": "Composite identifier of the freight quotation.\n",
      "example": "5100003410-1"
    },
    "OrderingPartyLbnId": {
      "type": "string",
      "maxLength": 40,
      "description": "Identifier of the ordering party within SAP Business Network for Logistics.\n",
      "example": "10000042"
    },
    "CarrierPartyLbnId": {
      "type": "string",
      "maxLength": 40,
      "description": "Identifier of the carrier within SAP Business Network for Logistics.\n",
      "example": "10000043"
    },
    "OriginatorId": {
      "type": "string",
      "maxLength": 60,
      "description": "Identifier of the originating system of the ordering party.\n",
      "example": "XYZ_123"
    },
    "NetworkPartner": {
      "type": "object",
      "properties": {
        "networkPartnerLBNID": {
          "type": "string",
          "example": "10000042",
          "description": "Identifier of the network partner within SAP Business Network for Logistics.\n",
          "maxLength": 35
        }
      }
    },
    "TransportationStageItemPostFreightQuotation": {
      "type": "object",
      "properties": {
        "id": {
          "type": "integer",
          "format": "int32",
          "example": 1,
          "description": "Identifier of the transportation stage.\n"
        },
        "proposedLoadingStartDateTime": {
          "type": "string",
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "example": "2018-12-31T23:59:00Z",
          "description": "Time when loading starts, as proposed by the carrier.\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "maxLength": 24,
          "default": "Timestamp as provided during creation of the freight request for quotation."
        },
        "proposedLoadingEndDateTime": {
          "type": "string",
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "example": "2018-12-31T23:59:00Z",
          "description": "Time when loading ends, as proposed by the carrier.\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "maxLength": 24,
          "default": "Time as provided during creation of the freight request for quotation."
        },
        "proposedUnloadingStartDateTime": {
          "type": "string",
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "example": "2018-12-31T23:59:00Z",
          "description": "Time when unloading starts, as proposed by the carrier.\nFormat must be compliant with RFC 3339 Internet date/time format.\n",
          "maxLength": 24,
          "default": "Time as provided during creation of the freight request for quotation."
        },
        "proposedUnloadingEndDateTime": {
          "type": "string",
          "format": "yyyy-MM-ddTHH:mm:ssZ",
          "example": "2018-12-31T23:59:00Z",
          "description": "Time when unloading ends, as proposed by the carrier.\nFormat must be compliant to RFC 3339 Internet date/time format.\n",
          "maxLength": 24,
          "default": "Times as provided during creation of the freight request for quotation."
        }
      },
      "description": "Information about a section of the transportation chain represented by a freight request for quotation.\n"
    },
    "Error": {
      "type": "object",
      "required": [
        "message"
      ],
      "properties": {
        "message": {
          "type": "string",
          "example": "Some error message",
          "description": "Error message\n"
        }
      }
    },
    "inline_response_201": {
      "properties": {
        "freightQuotationId": {
          "$ref": "#/definitions/CompositeFreightQuotationId"
        }
      }
    },
    "PostFreightQuotation_proposalPrice": {
      "properties": {
        "value": {
          "type": "number",
          "example": 1000,
          "description": "Amount that the carrier proposes as the charge for executing the freight request for quotation.\n",
          "x-precision": 28,
          "x-scale": 6
        },
        "currency": {
          "type": "string",
          "example": "USD",
          "description": "Format must be compliant with SAP Global Data Type `CurrencyCode` (`listID` = `4217`, `listAgencyID` = `5`). [Codelist](https://help.sap.com/docs/SAP_LBN_FC_OPTION/40f43410e8a64dc98792a5e610e81017/c5ff86c3b2c744b4aab2ade9d9b1f05e.html)\n",
          "maxLength": 3
        }
      },
      "description": "Amount that the carrier proposes as the charge for executing the freight request for quotation.\nPrice proposal can be used to propose an alternative price in case property `priceIsNegotiable` of the referenced freight request for quotation is `true`.\nPrice proposal is considered only in the case of accept (`responseCode` = `AP`).\nIn other cases it is ignored.\n"
    },
    "PostFreightQuotation_note": {
      "properties": {
        "text": {
          "type": "string",
          "description": "Natural-language text with additional information about the freight request for quotation.\nThe note is language-independent.\n",
          "maxLength": 3000
        }
      }
    },
    "Attachment": {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "description": "Name of the attachment along with the file extension.\n",
          "maxLength": 255,
          "example": "Document.pdf"
        },
        "mimeCode": {
          "type": "string",
          "description": "Content type code of the attachment.\n* image/jpeg - Mime code for image files with .jpeg extension\n* image/jpg - Mime code for image files with .jpg extension\n* image/png - Mime code for image files with .png extension\n* image/gif - Mime code for image files with .gif extension\n* image/tiff - Mime code for image files with .tiff extension\n* image/tiff-fx - Mime code for image files with .tiff-fx extension\n* application/pdf - Mime code for files with .pdf extension\n* application/msword - Mime code for files with .doc extension\n* application/vnd.openxmlformats-officedocument.wordprocessingml.document - Mime code for files with .docx extension\n* application/vnd.ms-excel - Mime code for files with .xls extension\n* application/vnd.openxmlformats-officedocument.spreadsheetml.sheet - Mime code for files with .xlsx extension\n",
          "maxLength": 255,
          "enum": [
            "image/jpeg",
            "image/jpg",
            "image/png",
            "image/gif",
            "image/tiff",
            "image/tiff-fx",
            "application/pdf",
            "application/msword",
            "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            "application/vnd.ms-excel",
            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
          ],
          "example": "application/pdf"
        },
        "fileContentBinaryObject": {
          "type": "string",
          "format": "byte",
          "description": "Attachment Content in Base 64 encoded format.\n"
        }
      }
    }
  },
  "x-sap-shortText": "Enables carriers to manage the freight requests for quotation process, including the created freight quotations.",
  "x-servers": [
    {
      "url": "https://api.logistics.eu.business-network.cloud.sap/http/v1",
      "description": "FreightTendering API endpoint for EU10 data center"
    },
    {
      "url": "https://api.logistics.us.business-network.cloud.sap/http/v1",
      "description": "FreightTendering API endpoint for US20 data center"
    }
  ]
}

file://api-specs/GTT_OrderEvents_Provide.content:
{
  "swagger": "2.0",
  "info": {
    "description": "You can use this inbound API provided by SAP Business Network for Logistics to post events for an order. The events will be posted in SAP Business Network for Logistics and then forwarded to the system where the order was initially created",
    "version": "1.0.2",
    "title": "Provider API for Order Events (GTT)"
  },
  "externalDocs": {
    "description": "SAP Business Network Global Track and Trace",
    "url": "https://help.sap.com/viewer/product/SAP_LBN_GTT_OPTION/LBN/en-US"
  },
  "host": "hostname",
  "x-sap-shortText": "Enables data contributors (such as network partners or carriers) to post events for a tracked order.",
  "x-servers": [
    {
      "url": "https://api.logistics.{region}.business-network.cloud.sap/http/http/v1/tracking/events",
      "description": "Productive OrderEvents API endpoint for EU10 data center",
      "templates": {
        "region": {
          "enum": [
            "eu",
            "us"
          ],
          "default": "eu",
          "description": "region"
        },
        "endpoint": {
          "enum": [
            "bn4lintegrationsuiteliveeu10-d2q5jmpt.authentication.eu10.hana.ondemand.com",
            "bn4lintegrationsuiteliveus20-0gohdecj.authentication.us20.hana.ondemand.com"
          ],
          "default": "bn4lintegrationsuiteliveeu10-d2q5jmpt.authentication.eu10.hana.ondemand.com",
          "description": "endpoint"
        }
      }
    }
  ],
  "security": [
    {
      "eu10": [
        "{identityzone}.custom-activity_view",
        "{identityzone}.custom-activity_confirm"
      ]
    },
    {
      "us20": [
        "{identityzone}.custom-activity_view",
        "{identityzone}.custom-activity_confirm"
      ]
    }
  ],
  "schemes": [
    "https"
  ],
  "produces": [
    "application/json"
  ],
  "consumes": [
    "application/json"
  ],
  "tags": [
    {
      "name": "Events",
      "description": "Tracked order events"
    }
  ],
  "paths": {
    "/OrderEvents/": {
      "post": {
        "tags": [
          "Events"
        ],
        "summary": "Creates an event in a tracked order in SAP Business Network for Logistics",
        "description": "Call this endpoint to post events to SAP Business Network for Logistics. With this, the shipper can see the events in their external system and in SAP Business Network for Logistics as well.",
        "operationId": "reporting events",
        "produces": [
          "application/json"
        ],
        "parameters": [
          {
            "in": "body",
            "name": "body",
            "description": "Event information to be posted.",
            "required": true,
            "schema": {
              "$ref": "#/definitions/PostOrderEvents"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Event posted successfully.",
            "schema": {
              "$ref": "#/definitions/PostOrderEvents"
            }
          },
          "400": {
            "description": "Bad Request",
            "schema": {
              "$ref": "#/definitions/ErrorResponse"
            }
          },
          "401": {
            "description": "Unauthorized"
          },
          "403": {
            "description": "Forbidden",
            "schema": {
              "$ref": "#/definitions/ErrorResponse"
            }
          },
          "404": {
            "description": "Not Found"
          }
        }
      }
    }
  },
  "securityDefinitions": {
    "OAuth2": {
      "type": "oauth2",
      "description": "If you are a new carrier or a carrier who is currently building integration, you do not need to request for a technical user as described above, but rather can create it yourself by following the steps below:\n1. Go to System Connections application.\n2. Click on Connection Settings.\n3. In the Inbound section, choose Multi-Cloud as the Integration Platform.\n4. Choose the scenarios that you need access for.\n5. Click Save (You will see a warning dialog, click Yes to proceed). On Save, the dialog is closed and you can click on Connection Settings again and this time, it should show an option to see the Service Credentials. You will see Client ID, Client Secret and Authentication URL that you can now use for calling BNL.\n",
      "tokenUrl": "https://{endpoint}/oauth/token?grant_type=client_credentials",
      "flow": "application",
      "scopes": {
        "{identityzone}.custom-activity_view": "Get custom activity step information.",
        "{identityzone}.custom-activity_confirm": "Confirm custom activity step information retrieval."
      }
    }
  },
  "definitions": {
    "PostOrderEvents": {
      "type": "object",
      "description": "Event information to be posted.",
      "required": [
        "technicalId",
        "shipper",
        "carrier"
      ],
      "properties": {
        "shipper": {
          "$ref": "#/definitions/shipper"
        },
        "carrier": {
          "$ref": "#/definitions/carrier"
        },
        "networkPartner": {
          "$ref": "#/definitions/networkPartner"
        },
        "technicalId": {
          "type": "string",
          "maxLength": 255,
          "description": "Unique identifier of the event within SAP Business Network for Logistics",
          "example": "xri://sap.com/id:LBN#10000001:QM7CLNT910:Shipment:100011111:GTT"
        },
        "orderId": {
          "type": "string",
          "maxLength": 255,
          "example": "300000001"
        },
        "trackId": {
          "type": "string",
          "maxLength": 255,
          "description": "Unique identifier from visibility provider or business partner"
        },
        "creationDateTimeUTC": {
          "type": "string",
          "maxLength": 29,
          "format": "YYYY-MM-DDTHH:MM:SS[.sss]±HH:MM , YYYY-MM-DDTHH:MM:SS[.sss]Z",
          "example": "2024-11-21T10:08:45.213+01:00 or 2021-09-23T22:10:00Z",
          "description": "You must input UTC time or local time with UTC offsets."
        },
        "events": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/event"
          }
        }
      }
    },
    "shipper": {
      "type": "object",
      "description": "Identifier of the shipper within SAP Business Network for Logistics",
      "required": [
        "shipperLBNID"
      ],
      "properties": {
        "shipperLBNID": {
          "type": "string",
          "maxLength": 35,
          "example": "10000001"
        },
        "alternateId": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/alternateId"
          }
        }
      }
    },
    "carrier": {
      "type": "object",
      "description": "Identifier of the carrier within SAP Business Network for Logistics",
      "properties": {
        "carrierLBNID": {
          "type": "string",
          "maxLength": 35,
          "example": "10000002"
        },
        "alternateId": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/alternateId"
