{
  "swagger": "2.0",
  "info": {
    "description": "You can use this outbound API consumed by SAP Business Network for Logistics to create or update a tracking request in your external system. The API to be called and the authentication details are configured in the System Connections app. SAP Business Network for Logistics will call the configured endpoint based on the payload documented in this API.",
    "version": "1.0.0",
    "title": "Consumer API for Order Tracking (GTT)"
  },
  "externalDocs": {
    "description": "SAP Business Network Global Track and Trace",
    "url": "https://help.sap.com/viewer/product/SAP_LBN_GTT_OPTION/LBN/en-US"
  },
  "host": "hostname",
  "x-sap-shortText": "Enables solution owners to send a tracking request for an order to data contributors.",
  "x-servers": [
    {
      "url": "https://{host}:{port}/{basePath}",
      "description": "Test system endpoint",
      "templates": {
        "host": {
          "description": "Test system host"
        },
        "port": {
          "description": "Test system port"
        },
        "basePath": {
          "description": "Test system base path"
        }
      }
    }
  ],
  "security": [
    {
      "oauth2": [
        "{identityzone}.custom-activity_view",
        "{identityzone}.custom-activity_confirm"
      ]
    }
  ],
  "schemes": [
    "https"
  ],
  "tags": [
    {
      "name": "Order",
      "description": "An order from SAP Business Network for Logistics"
    }
  ],
  "paths": {
    "/LBNOrderForTracking/": {
      "put": {
        "tags": [
          "Order"
        ],
        "summary": "Creates or updates a tracking request in your system",
        "consumes": [
          "application/json"
        ],
        "description": "SAP Business Network for Logistics will make a call to the configured endpoint to create or update a tracking request. The call follows an upsert behaviour. You need to check if the call is a first post call or an update call.",
        "parameters": [
          {
            "in": "body",
            "name": "body",
            "description": "An order for tracking to be created",
            "required": true,
            "schema": {
              "$ref": "#/definitions/PutOrderForTracking"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Order for tracking updated",
            "schema": {
              "type": "object",
              "required": [
                "trackId"
              ],
              "properties": {
                "trackId": {
                  "$ref": "#/definitions/trackId"
                },
                "sku": {
                  "$ref": "#/definitions/sku"
                }
              }
            }
          },
          "201": {
            "description": "Order for tracking created",
            "schema": {
              "type": "object",
              "required": [
                "trackId"
              ],
              "properties": {
                "trackId": {
                  "$ref": "#/definitions/trackId"
                },
                "sku": {
                  "$ref": "#/definitions/sku"
                }
              }
            }
          },
          "400": {
            "description": "Bad Request",
            "schema": {
              "$ref": "#/definitions/ErrorResponse"
            }
          },
          "401": {
            "description": "Unauthorized"
          },
          "403": {
            "description": "Forbidden",
            "schema": {
              "$ref": "#/definitions/ErrorResponse"
            }
          },
          "404": {
            "description": "Not Found"
          }
        }
      },
      "delete": {
        "tags": [
          "Order"
        ],
        "summary": "Deletes a tracking request in your system.",
        "consumes": [
          "application/json"
        ],
        "description": "SAP Business Network for Logistics will make a call to the configured endpoint to delete a tracking request. TechnicalId should be will the key information to be used to identify the delete object",
        "parameters": [
          {
            "in": "body",
            "name": "body",
            "description": "An order for tracking to be deleted.",
            "required": true,
            "schema": {
              "$ref": "#/definitions/DeleteOrderForTracking"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Tracking deleted or cancelled",
            "schema": {
              "$ref": "#/definitions/DeleteOrderForTracking"
            }
          },
          "204": {
            "description": "Tracking deleted or cancelled"
          },
          "400": {
            "description": "Bad Request",
            "schema": {
              "$ref": "#/definitions/ErrorResponse"
            }
          },
          "401": {
            "description": "Unauthorized"
          },
          "403": {
            "description": "Forbidden",
            "schema": {
              "$ref": "#/definitions/ErrorResponse"
            }
          },
          "404": {
            "description": "Not Found"
          }
        }
      }
    }
  },
  "securityDefinitions": {
    "basicAuthentication": {
      "type": "basic"
    }
  },
