{
  "swagger": "2.0",
  "info": {
    "title": "Provider API for Invoicing",
    "description": "Provides functionality for managing invoicing process when integrating SAP Logistics Business Network with other systems.\nThis specification describes the API from the perspective of SAP Logistics Business Network as the provider of the API.\nOther systems call the defined endpoints within SAP Logistics Business Network.\n",
    "version": "1.1.0",
    "contact": {
      "name": "lbn@sap.com"
    },
    "termsOfService": ""
  },
  "x-sap-shortText": "Enables carriers to manage invoicing process.",
  "x-servers": [
    {
      "url": "https://api.logistics.eu.business-network.cloud.sap/http/v1",
      "description": "Invoice API endpoint for EU10 data center"
    },
    {
      "url": "https://api.logistics.us.business-network.cloud.sap/http/v1",
      "description": "Invoice API endpoint for US20 data center"
    }
  ],
  "host": "hostname",
  "externalDocs": {
    "description": "Click here to access detailed implementation documentation.",
    "url": "https://help.sap.com/doc/e1b2026259d84fc29e6e6760da815011/LBN/en-US/b3d48de6a89e411c9106adb8498a2bda.html"
  },
  "securityDefinitions": {
    "eu10": {
      "type": "oauth2",
      "description": "To use the EU10 data center API, you must obtain the OAuth client credentials (client ID and secret). \nTo get the OAuth client credentials, create a customer incident on SAP support portal with the component as SBN-LBN-INT. \nProvide the SAP Business Network for Logistics ID created for your account and the email address to receive your client credentials. \nSpecify the target integration platform as ‘Multi-Cloud (new)’ and the title as ‘SAP BN4L Integration Platform Migration: Request for new OAuth 2.0 credential’. \nOnce you receive the credentials, pass the details to SAP HANA Cloud Platform token endpoint to obtain an access token.\n",
      "tokenUrl": "https://bn4lintegrationsuiteliveeu10-d2q5jmpt.authentication.eu10.hana.ondemand.com/oauth/token?grant_type=client_credentials",
      "flow": "application",
      "scopes": {
        "{identityzone}.custom-activity_view": "Get custom activity step information.",
        "{identityzone}.custom-activity_confirm": "Confirm custom activity step information retrieval."
      }
    },
    "us20": {
      "type": "oauth2",
      "description": "To use the US20 data center API, you must obtain the OAuth client credentials (client ID and secret). \nTo get the OAuth client credentials, create a customer incident on SAP support portal with the component as SBN-LBN-INT. \nProvide the SAP Business Network for Logistics ID created for your account and the email address to receive your client credentials. \nSpecify the target integration platform as ‘Multi-Cloud (new)’ and the title as ‘SAP BN4L Integration Platform Migration: Request for new OAuth 2.0 credential’. \nOnce you receive the credentials, pass the details to SAP HANA Cloud Platform token endpoint to obtain an access token.\n",
      "tokenUrl": "https://bn4lintegrationsuiteliveus20-0gohdecj.authentication.us20.hana.ondemand.com/oauth/token?grant_type=client_credentials",
      "flow": "application",
      "scopes": {
        "{identityzone}.custom-activity_view": "Get custom activity step information.",
        "{identityzone}.custom-activity_confirm": "Confirm custom activity step information retrieval."
      }
    }
  },
  "security": [
    {
      "eu10": [
        "{identityzone}.custom-activity_view",
        "{identityzone}.custom-activity_confirm"
      ]
    },
    {
      "us20": [
        "{identityzone}.custom-activity_view",
        "{identityzone}.custom-activity_confirm"
      ]
    }
  ],
  "schemes": [
    "https"
  ],
  "produces": [
    "application/json"
  ],
  "consumes": [
    "application/json"
  ],
  "tags": [
    {
      "name": "Carrier Invoice"
    }
  ],
  "paths": {
    "/LogisticsInvoice": {
      "post": {
        "operationId": "createCarrierInvoice",
        "summary": "Public API for carrier to create an invoice request.",
        "description": "Create a new invoice\n",
        "tags": [
          "Invoice"
        ],
        "parameters": [
          {
            "name": "invoice",
            "in": "body",
            "description": "Creates an invoice",
            "required": true,
            "schema": {
              "$ref": "#/definitions/CarrierInvoiceRest"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Carrier invoice is created",
            "schema": {
              "type": "object"
            }
          },
          "400": {
            "description": "Malformed payload",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "401": {
            "description": "Unauthorized",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "403": {
            "description": "Forbidden",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "500": {
            "description": "Internal Server Error",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          }
        }
      }
    }
  },
  "definitions": {
    "CarrierInvoiceRest": {
      "type": "object",
      "required": [
        "carrierInvoiceID",
        "invoiceDate",
        "grossAmount",
        "grossAmountCurrency",
        "orderingPartyLbnId",
        "carrierLbnId",
        "purchasingParty",
        "billFromParty",
        "baseDocumentType",
        "senderSystemId"
      ],
      "properties": {
        "carrierInvoiceID": {
          "type": "string",
          "maxLength": 16,
          "description": "Identifier of carrier invoice\n"
        },
        "invoiceDate": {
          "$ref": "#/definitions/DateTimeType"
        },
        "grossAmount": {
          "type": "number",
          "x-precision": 28,
          "x-scale": 6,
          "description": "Enter the total amount of all items in a carrier invoice including the tax amount. Specifies the gross invoice amount in the document currency.\n",
          "example": "1000.50"
        },
        "grossAmountCurrency": {
          "type": "string",
          "maxLength": 3,
          "description": "Enter the currency of gross amount.\nFormat must be compliant with SAP Global Data Type `CurrencyCode` (`listID` = `4217`, `listAgencyID` = `5`).\n",
          "example": "USD"
        },
        "orderingPartyLbnId": {
          "type": "string",
          "maxLength": 40,
          "description": "Identifier of the ordering party in SAP Logistics Business Network system.\n",
          "example": "10000042"
        },
        "carrierLbnId": {
          "type": "string",
          "maxLength": 40,
          "description": "Identifier of the carrier in SAP Logistics Business Network system.\n",
          "example": "10000043"
        },
        "baseDocumentType": {
          "$ref": "#/definitions/BaseDocumentType"
        },
        "purchasingParty": {
          "type": "string",
          "maxLength": 40,
          "description": "Specify the ordering party in the shipper's system.\n"
        },
        "billFromParty": {
          "type": "string",
          "maxLength": 40,
          "description": "Specify the carrier in the shipper's system.\n"
        },
        "totalTaxAmount": {
          "type": "number",
          "x-precision": 28,
          "x-scale": 6,
          "description": "Enter the total amount of all tax lines included in an invoice.\n",
          "example": "0.50"
        },
        "taxAmountCurrency": {
          "type": "string",
          "maxLength": 3,
          "description": "Specify the currency of tax amount.\nFormat must be compliant with SAP Global Data Type `CurrencyCode` (`listID` = `4217`, `listAgencyID` = `5`).\n",
          "example": "USD"
        },
        "senderSystemId": {
          "type": "string",
          "maxLength": 60,
          "description": "Unique identifier of the shipper system\n",
          "example": "QM7_910"
        },
        "items": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/Item"
          },
          "description": "Specify the charge items in the invoice.\n"
        },
        "documentReferences": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/DocumentReference"
          },
          "description": "Document references present in the invoice.\n"
        },
        "notes": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/Note"
          },
          "description": "Specify additional information about the carrier invoice.\n"
        },
        "attachments": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/AttachmentRest"
          },
          "description": "Specify attachments in a binary format.\n"
        }
      }
    },
    "BaseDocumentType": {
      "type": "string",
      "enum": [
        "1122",
        "610"
      ],
      "example": "1122",
      "description": "Specify the type of base document.\n\"1122\" - Freight order document\n\"610\" - Freight booking document\n"
    },
    "DocumentReference": {
      "type": "object",
      "required": [
        "documentTypeCode",
        "documentId"
      ],
      "properties": {
        "documentTypeCode": {
          "type": "string",
          "maxLength": 5,
          "description": "A coded representation of the type of business document that is referenced. [Codelist](https://help.sap.com/docs/business-network-freight-collaboration/code-lists/document-reference-type-codes)\n",
          "example": "1122"
        },
        "documentId": {
          "type": "string",
          "maxLength": 35,
          "description": "An identifier for a referenced business document.\n"
        }
      }
    },
    "Item": {
      "type": "object",
      "required": [
        "grossAmount",
        "grossAmountCurrency"
      ],
      "properties": {
        "grossAmount": {
          "type": "number",
          "x-precision": 28,
          "x-scale": 6,
          "description": "Specify the total amount of the underlying pricing elements in the document currency including the tax amount.\n",
          "example": "1000.50"
        },
        "grossAmountCurrency": {
          "type": "string",
          "maxLength": 3,
          "description": "Specify the currency of gross amount.\nFormat must be compliant with SAP Global Data Type `CurrencyCode` (`listID` = `4217`, `listAgencyID` = `5`).\n",
          "example": "USD"
        },
        "freightDocumentID": {
          "type": "string",
          "maxLength": 20,
          "description": "Identifier of the freight document used in the invoice. Contains the freight document number in the shipper's system.\n"
        },
        "transportationItemID": {
          "type": "string",
          "maxLength": 10,
          "description": "Identifier of a cargo item. Contains the item ID of the freight document item in the shipper's system if the invoice item is for a freight document item. Only required when the calculation level in SAP TM for the carrier is item level.\n",
          "example": "10"
        },
        "transportationStageID": {
          "type": "string",
          "maxLength": 10,
          "description": "Identifier of a stage. Holds the sender system stage ID. Only required when the calculation level in SAP TM for the carrier is stage level. Contains the stage ID of the freight document stage in the shipper's system if the invoice item is for a freight document stage.\n",
          "example": "20"
        },
        "alternateIDCategory": {
          "type": "string",
          "maxLength": 35,
          "description": "Specifies the type of alternate ID used to identify the freight document.\nWhen provided, only the following values are allowed:\n  - MBL_CONTAINERID\n  - BOOKINGREF_CONTAINERID\n"
        },
        "alternateIDs": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/AlternateID"
          }
        },
        "itemTaxes": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/ItemTax"
          }
        },
        "pricingElements": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/PricingElement"
          }
        }
      }
    },
    "AlternateID": {
      "type": "object",
      "required": [
        "typeCode",
        "id"
      ],
      "properties": {
        "typeCode": {
          "type": "string",
          "maxLength": 5,
          "description": "A coded representation of the type of alternate ID provided.[Codelist](https://help.sap.com/docs/business-network-freight-collaboration/code-lists/document-reference-type-codes)\n  Allowed Values – Description:\n    -T52: Master Bill of Lading\n    -CONT: Container ID\n    -BREF: Booking Reference\n",
          "example": "T52"
        },
        "id": {
          "type": "string",
          "maxLength": 35,
          "description": "An identifier for an alternate ID."
        }
      }
    },
    "ItemTax": {
      "type": "object",
      "required": [
        "taxCode",
        "taxPercentage",
        "taxAmount",
        "taxAmountCurrency"
      ],
      "properties": {
        "taxCode": {
          "type": "string",
          "maxLength": 3,
          "description": "Enter the supplier tax type code.\n",
          "example": "VAT"
        },
        "taxPercentage": {
          "type": "number",
          "example": "18.0"
        },
        "taxAmount": {
          "type": "number",
          "x-precision": 28,
          "x-scale": 6,
          "description": "Enter the tax amount in document currency.\n",
          "example": "0.5"
        },
        "taxAmountCurrency": {
          "type": "string",
          "maxLength": 3,
          "description": "Specify the currency of tax amount.\nFormat must be compliant with SAP Global Data Type `CurrencyCode` (`listID` = `4217`, `listAgencyID` = `5`).\n",
          "example": "USD"
        }
      }
    },
    "PricingElement": {
      "type": "object",
      "required": [
        "lbnChargeCode",
        "rateAmount",
        "rateAmountCurrency",
        "finalAmount",
        "finalAmountCurrency"
      ],
      "properties": {
        "lbnChargeCode": {
          "type": "string",
          "maxLength": 15,
          "description": "Enter the charge code maintained in SAP Business Network for Logistics. Please contact your shipper for the charge code that they have maintained in their Assign Charge Codes app. Note that you must enter only the code and not the description.\n",
          "example": "TOLLS"
        },
        "rateAmount": {
          "type": "number",
          "x-precision": 28,
          "x-scale": 6,
          "description": "Specify the rate agreed with the carrier.\n",
          "example": "1000.00"
        },
        "rateAmountCurrency": {
          "type": "string",
          "maxLength": 3,
          "description": "Specify the currency of rate amount.\nFormat must be compliant with SAP Global Data Type `CurrencyCode` (`listID` = `4217`, `listAgencyID` = `5`).\n",
          "example": "USD"
        },
        "finalAmount": {
          "type": "number",
          "x-precision": 28,
          "x-scale": 6,
          "description": "Enter the invoice amount for the component invoiced by the carrier in document currency.\n",
          "example": "1000.00"
        },
        "finalAmountCurrency": {
          "type": "string",
          "maxLength": 3,
          "description": "Specify the currency of final amount.\nFormat must be compliant with SAP Global Data Type `CurrencyCode` (`listID` = `4217`, `listAgencyID` = `5`).\n",
          "example": "USD"
        },
        "quantity": {
          "type": "number",
          "x-precision": 31,
          "x-scale": 14,
          "example": "51.0"
        },
        "quantityUnit": {
          "type": "string",
          "maxLength": 3,
          "description": "Specify the unit of quantity.\nFormat must be compliant with `Common Codes` specified in UN/CEFACT Recommendation #20.\n",
          "example": "KGM"
        },
        "priceUnit": {
          "type": "number",
          "x-precision": 31,
          "x-scale": 14,
          "example": "1.0"
        },
        "priceUnitUoM": {
          "type": "string",
          "maxLength": 3,
          "description": "Specify the unit of measure of price unit.\nFormat must be compliant with `Common Codes` specified in UN/CEFACT Recommendation #20.\n",
          "example": "KGM"
        },
        "logisticalContext": {
          "type": "string",
          "maxLength": 60,
          "description": "Enter the logistical reference value of the charge line. Logistical reference displays the header or item or stage information for a charge line (for the resolution base of container, package, product, stage, etc) from which the system obtains the logistical data.\n",
          "example": "10"
        },
        "logisticalContextType": {
          "$ref": "#/definitions/LogisticalContextType"
        }
      }
    },
    "LogisticalContextType": {
      "type": "string",
      "enum": [
        "ACTIVE_RESOURCE",
        "BOOKING",
        "CONTAINER",
        "MAIN_ITEM",
        "PACKAGE",
        "PASSIVE_RESOURCE",
        "PRODUCT",
        "RESOURCE",
        "ROOT",
        "SERVICE",
        "STAGE"
      ],
      "example": "PRODUCT",
      "description": "Enter the logistical reference type. Enter a value specified in enum.\n"
    },
    "Note": {
      "type": "object",
      "properties": {
        "text": {
          "type": "string",
          "maxLength": 1023,
          "description": "Enter additional information about the carrier invoice.\n"
        },
        "language": {
          "type": "string",
          "maxLength": 4,
          "example": "en"
        }
      }
    },
    "AttachmentRest": {
      "type": "object",
      "required": [
        "fileName",
        "mimeType",
        "fileContentBinaryObject"
      ],
      "properties": {
        "fileName": {
          "type": "string",
          "maxLength": 255,
          "description": "Specify the name of the attachment.\n"
        },
        "mimeType": {
          "type": "string",
          "maxLength": 128,
          "description": "Content type code of the attachment.\n* image/jpg - MIME type for image files with .jpg extension\n* image/jpeg - MIME type for image files with .jpeg extension\n* image/png - MIME type for image files with .png extension\n* image/gif - MIME type for image files with .gif extension\n* image/tiff - MIME type for image files with the .tif (Windows) or .tiff (Mac) extension\n* image/tiff-fx - MIME type for image files with the .tfx extension (Windows and Mac)\n* application/pdf - MIME type for files with .pdf extension\n* application/msword - MIME type for files with .doc extension\n* application/vnd.openxmlformats-officedocument.wordprocessingml.document - MIME type for files with .docx extension\n* application/vnd.ms-excel - MIME type for files with .xls extension\n* application/vnd.openxmlformats-officedocument.spreadsheetml.sheet - MIME type for files with .xlsx extension\n"
        },
        "fileContentBinaryObject": {
          "type": "string",
          "format": "binary",
          "description": "Enter the attachment content in binary format. Note that the maximum size of the attachment must not exceed 5 MB.\n"
        }
      }
    },
    "DateTimeType": {
      "type": "string",
      "description": "Enter the date of creation of invoice. Note even when you enter the date and time in this field, the system only displays the date in the external transportation system.\nFormat must be compliant with RFC 3339 internet date/time format (yyyy-MM-ddTHH:mm:ssZ)\n",
      "example": "2018-12-31T23:59:59Z"
    },
    "Error": {
      "type": "object",
      "properties": {
        "code": {
          "type": "string",
          "description": "Internal message key"
        },
        "message": {
          "type": "string",
          "description": "Localized message"
        },
        "target": {
          "type": "string",
          "description": "Identifier of UI element"
        },
        "severity": {
          "type": "string",
          "description": "Classification of error severity"
        }
      }
    }
  }
}

file://api-specs/OrderEvents_Provider (2.content:
{
  "swagger": "2.0",
  "info": {
    "description": "You can use this inbound API provided by SAP Business Network for Logistics to post events for an order. The events will be posted in SAP Business Network for Logistics and then forwarded to the system where the order was initially created",
    "version": "1.0.4",
    "title": "Provider API for Order Events (FC)"
  },
  "externalDocs": {
    "description": "SAP Business Network for Logistics - Configuring URLs via system connection",
    "url": "https://help.sap.com/viewer/185742008f2c477ca789b93675b0ec6c/LBN/en-US/011fbcd85017450587389c4a10190077.html"
  },
  "x-sap-shortText": "Enables data contributors (such as network partners or carriers) to post events for a tracked order.",
  "x-servers": [
    {
      "url": "https://api.logistics.{region}.business-network.cloud.sap/http/http/v1/tracking/events",
      "description": "Productive OrderEvents API endpoint for EU10 data center",
      "templates": {
        "region": {
          "enum": [
            "eu",
            "us"
          ],
          "default": "eu",
          "description": "region"
        },
        "endpoint": {
          "enum": [
            "bn4lintegrationsuiteliveeu10-d2q5jmpt.authentication.eu10.hana.ondemand.com",
            "bn4lintegrationsuiteliveus20-0gohdecj.authentication.us20.hana.ondemand.com"
          ],
          "default": "bn4lintegrationsuiteliveeu10-d2q5jmpt.authentication.eu10.hana.ondemand.com",
          "description": "endpoint"
        }
      }
    }
  ],
  "security": [
    {
      "eu10": [
        "{identityzone}.custom-activity_view",
        "{identityzone}.custom-activity_confirm"
      ]
    },
    {
      "us20": [
        "{identityzone}.custom-activity_view",
        "{identityzone}.custom-activity_confirm"
      ]
    }
  ],
  "schemes": [
    "https"
  ],
  "produces": [
    "application/json"
  ],
  "consumes": [
    "application/json"
  ],
  "tags": [
    {
      "name": "Events",
      "description": "Tracked order events"
    }
  ],
  "paths": {
    "/OrderEvents/": {
      "post": {
        "tags": [
          "Events"
        ],
        "summary": "Creates an event in a tracked order in SAP Business Network for Logistics",
        "description": "Call this endpoint to post events to LBN. With this, the shipper can see the events in their external system and in SAP Business Network for Logistics as well.",
        "operationId": "reporting events",
        "produces": [
          "application/json"
        ],
        "parameters": [
          {
            "in": "body",
            "name": "body",
            "description": "Event information to be posted.",
            "required": true,
            "schema": {
              "$ref": "#/definitions/PostOrderEvents"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Event posted successfully.",
            "schema": {
              "$ref": "#/definitions/PostOrderEvents"
            }
          },
          "400": {
            "description": "Bad Request",
            "schema": {
              "$ref": "#/definitions/ErrorResponse"
            }
          },
          "401": {
            "description": "Unauthorized"
          },
          "403": {
            "description": "Forbidden",
            "schema": {
              "$ref": "#/definitions/ErrorResponse"
            }
          },
          "404": {
            "description": "Not Found"
          }
        }
      }
    }
  },
  "securityDefinitions": {
    "OAuth2": {
      "type": "oauth2",
      "description": "If you are a new carrier or a carrier who is currently building integration, you do not need to request for a technical user as described above, but rather can create it yourself by following the steps below:\n1. Go to System Connections application.\n2. Click on Connection Settings.\n3. In the Inbound section, choose Multi-Cloud as the Integration Platform.\n4. Choose the scenarios that you need access for.\n5. Click Save (You will see a warning dialog, click Yes to proceed). On Save, the dialog is closed and you can click on Connection Settings again and this time, it should show an option to see the Service Credentials. You will see Client ID, Client Secret and Authentication URL that you can now use for calling BNL.\n",
      "tokenUrl": "https://{endpoint}/oauth/token?grant_type=client_credentials",
      "flow": "application",
      "scopes": {
        "{identityzone}.custom-activity_view": "Get custom activity step information.",
        "{identityzone}.custom-activity_confirm": "Confirm custom activity step information retrieval."
      }
    }
  },
  "definitions": {
    "PostOrderEvents": {
      "type": "object",
      "description": "Event information to be posted.",
      "required": [
        "technicalId",
        "shipper",
        "carrier"
      ],
      "properties": {
        "shipper": {
          "$ref": "#/definitions/shipper"
        },
        "carrier": {
          "$ref": "#/definitions/carrier"
        },
        "networkPartner": {
          "$ref": "#/definitions/networkPartner"
        },
        "technicalId": {
          "type": "string",
          "maxLength": 255,
          "description": "Unique identifier of the event within SAP Business Network for Logistics",
          "example": "xri://sap.com/id:LBN#10000001:QM7CLNT910:FreightOrder:100011111:FC"
        },
        "orderId": {
          "type": "string",
          "maxLength": 255,
          "example": "300000001"
        },
        "trackId": {
          "type": "string",
          "maxLength": 255,
          "description": "Unique identifier from visibility provider or business partner"
        },
        "creationDateTimeUTC": {
          "type": "string",
          "maxLength": 29,
          "format": "2024-11-21T10:08:45.213+01:00 , 2021-09-23T22:10:00Z",
          "example": "2024-11-21T10:08:45.213+01:00 or 2021-09-23T22:10:00Z",
          "description": "You must input UTC time or local time with UTC offsets."
        },
        "events": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/event"
          }
        }
      }
    },
    "shipper": {
      "type": "object",
      "description": "Identifier of the shipper within SAP Business Network for Logistics",
      "required": [
        "shipperLBNID"
      ],
      "properties": {
        "shipperLBNID": {
          "type": "string",
          "maxLength": 35,
          "example": "10000001"
        },
        "alternateId": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/alternateId"
          }
        }
      }
    },
    "carrier": {
      "type": "object",
      "description": "Identifier of the carrier within SAP Business Network for Logistics",
      "properties": {
        "carrierLBNID": {
          "type": "string",
          "maxLength": 35,
          "example": "10000002"
        },
        "alternateId": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/alternateId"
          }
        }
      }
    },
    "networkPartner": {
      "type": "object",
      "description": "Identifier of the network partner within SAP Business Network for Logistics",
      "properties": {
        "networkPartnerLBNID": {
          "type": "string",
          "maxLength": 35,
          "example": "10010000001"
        }
      }
    },
    "alternateId": {
      "type": "object",
      "properties": {
        "key": {
          "description": "Alternate ID types * SCAC - SCAC * P44_EU - P44_EU * MC - Motor Carrier Number * USDOT - US DOT * GLN - GLN * VAT - VAT * SAPBPID - SAP Business Partner Number",
          "type": "string",
          "maxLength": 35
        },
        "value": {
          "type": "string",
          "maxLength": 255
        }
      }
    },
    "event": {
      "type": "object",
      "required": [
        "eventType",
        "natureOfEvent",
        "eventDateTimeUTC"
      ],
      "properties": {
        "natureOfEvent": {
          "description": "Specifies the nature of data recorded for the event * 01 - Reported * 02 - Computed",
          "type": "string",
          "example": "02",
          "enum": [
            "01",
            "02"
          ]
        },
        "reportedBy": {
          "description": "Specifies the source of event",
          "type": "string",
          "maxLength": 255,
          "example": "CARRIER"
        },
        "isFinal": {
          "description": "Specifies if the event is the last event of the tracking or not",
          "type": "boolean",
          "example": false
        },
        "eventType": {
          "description": "Specifies the event to be recorded. * DEPARTURE - Departure, * ARRIV_DEST - Arrival, * LOAD_BEGIN - Loading Start, * LOAD_END - Loading End, * UNLOAD_BEGIN - Unloading Start, * UNLOAD_END - Unloading End, * COUPLING  - Coupling, * DECOUPLING - Decoupling, * POPU  - Proof of Pick-Up, * POD - Proof of Delivery, * DELAYED - Delay, * GEOLOC - Geo Location Update, * RECEIVE - Receive, * STUFF - Stuff, * UNSTUFF - Unstuff, * GATEIN_START - Gate-in Start, * GATEIN_END - Gate-in End, * GATEOUT_START - Gate-out Start, * GATEOUT_END - Gate-out End, * DELIVERED - Delivered, * RETURN - Return, * OTHER - Other, * OUT_FOR_DELIVERY - Out for Delivery, * EXCEPTION - Exception, * FLIGHT_BOOKED - Flight Booked, * MANIFEST_READY - Manifest Ready, * RCVD_FROM_SHIPPER - Cargo Received from Shipper, * CONSIGNEE_NOTIFIED - Consignee Notified, * EVENT_EST_UPD - Event Estimate Update, * EMISSION - Emission Event, * CUSTOMS_HOLD_START - Customs Hold Start, * CUSTOMS_HOLD_END - Customs Hold End, * TECHNICAL_USE - Technical Use, * PICKUP_END - Pick-up End, * GATEOUT_EMPTY - Gate-out Empty, * GATEIN_FULL - Gate-in Full, * GATEOUT_FULL - Gate-out Full, * GATEIN_EMPTY - Gate-in Empty, * READY_FOR_PICKUP - Ready for Pickup, * HANDOVER - Handover, * ON_TIME - On Time, * CARRIER_NOTIFIED - Carrier Notified, * READY_FOR_CARRIAGE - Ready for Carriage, * RCVD_FROM_CARRIER - Received from Carrier, * GATEIN_CANCELED - Gate Check-In Canceled, * CARRIER_CONFIRMED - Carrier Confirmed, * CROSSDOCK_HANDOVER - Cross-Dock Handover, * CNTR_PROV - Container Provisioned, * EXCEPTION_RESOLVED - Exception Resolved, * SLOT_BOOKING - Slot Booking, * CHECK_IN - Check In, * SUB_VEHICLE_READY - Subsequent Vehicle Ready, * GATEIN_HOLD - Gate Check-In on Hold For more, see the Code Lists document https://help.sap.com/docs/business-network-global-track-and-trace/code-lists/event-code-descriptions",
          "type": "string",
          "maxLength": 20,
          "example": "DEPARTURE",
          "enum": [
            "DEPARTURE",
            "ARRIV_DEST",
            "LOAD_BEGIN",
            "LOAD_END",
            "UNLOAD_BEGIN",
            "UNLOAD_END",
            "COUPLING",
            "DECOUPLING",
            "POPU",
            "POD",
            "DELAYED",
            "GEOLOC",
            "RECEIVE",
            "STUFF",
            "UNSTUFF",
            "GATEIN_START",
            "GATEIN_END",
            "GATEOUT_START",
            "GATEOUT_END",
            "DELIVERED",
            "RETURN",
            "OTHER",
            "OUT_FOR_DELIVERY",
            "EXCEPTION",
            "FLIGHT_BOOKED",
            "MANIFEST_READY",
            "RCVD_FROM_SHIPPER",
            "CONSIGNEE_NOTIFIED",
            "EVENT_EST_UPD",
            "EMISSION",
            "CUSTOMS_HOLD_START",
            "CUSTOMS_HOLD_END",
            "TECHNICAL_USE",
            "PICKUP_END",
            "GATEOUT_EMPTY",
            "GATEIN_FULL",
            "GATEOUT_FULL",
            "GATEIN_EMPTY",
            "READY_FOR_PICKUP",
            "HANDOVER",
            "ON_TIME",
            "CARRIER_NOTIFIED",
            "READY_FOR_CARRIAGE",
            "RCVD_FROM_CARRIER",
            "GATEIN_CANCELED",
            "CARRIER_CONFIRMED",
            "CROSSDOCK_HANDOVER",
            "CNTR_PROV",
            "EXCEPTION_RESOLVED",
            "SLOT_BOOKING",
            "CHECK_IN",
            "SUB_VEHICLE_READY",
            "GATEIN_HOLD"
          ]
        },
        "referenceEventType": {
          "description": "Specifies the reference event to which the event is recorded. E.g. Delay at arrival. The Event type will be delayed and reference event type will be Arrival. * DEPARTURE - Departure, * ARRIV_DEST - Arrival, * LOAD_BEGIN - Loading Start, * LOAD_END - Loading End, * UNLOAD_BEGIN - Unloading Start, * UNLOAD_END - Unloading End, * COUPLING  - Coupling, * DECOUPLING - Decoupling, * POPU  - Proof of Pick-Up, * POD - Proof of Delivery, * DELAYED - Delay, * GEOLOC - Geo Location Update, * RECEIVE - Receive, * STUFF - Stuff, * UNSTUFF - Unstuff, * GATEIN_START - Gate-in Start, * GATEIN_END - Gate-in End, * GATEOUT_START - Gate-out Start, * GATEOUT_END - Gate-out End, * DELIVERED - Delivered, * RETURN - Return, * OTHER - Other, * OUT_FOR_DELIVERY - Out for Delivery, * EXCEPTION - Exception, * FLIGHT_BOOKED - Flight Booked, * MANIFEST_READY - Manifest Ready, * RCVD_FROM_SHIPPER - Cargo Received from Shipper, * CONSIGNEE_NOTIFIED - Consignee Notified, * EVENT_EST_UPD - Event Estimate Update, * EMISSION - Emission Event, * CUSTOMS_HOLD_START - Customs Hold Start, * CUSTOMS_HOLD_END - Customs Hold End, * TECHNICAL_USE - Technical Use, * PICKUP_END - Pick-up End, * GATEOUT_EMPTY - Gate-out Empty, * GATEIN_FULL - Gate-in Full, * GATEOUT_FULL - Gate-out Full, * GATEIN_EMPTY - Gate-in Empty, * READY_FOR_PICKUP - Ready for Pickup, * HANDOVER - Handover, * ON_TIME - On Time, * CARRIER_NOTIFIED - Carrier Notified, * READY_FOR_CARRIAGE - Ready for Carriage, * RCVD_FROM_CARRIER - Received from Carrier, * GATEIN_CANCELED - Gate Check-In Canceled, * CARRIER_CONFIRMED - Carrier Confirmed, * CROSSDOCK_HANDOVER - Cross-Dock Handover, * CNTR_PROV - Container Provisioned, * EXCEPTION_RESOLVED - Exception Resolved, * SLOT_BOOKING - Slot Booking, * CHECK_IN - Check In, * SUB_VEHICLE_READY - Subsequent Vehicle Ready, * GATEIN_HOLD - Gate Check-In on Hold",
          "type": "string",
          "maxLength": 20,
          "example": "DEPARTURE",
          "enum": [
            "DEPARTURE",
            "ARRIV_DEST",
            "LOAD_BEGIN",
            "LOAD_END",
            "UNLOAD_BEGIN",
            "UNLOAD_END",
            "COUPLING",
            "DECOUPLING",
            "POPU",
            "POD",
            "DELAYED",
            "GEOLOC",
            "RECEIVE",
            "STUFF",
            "UNSTUFF",
            "GATEIN_START",
            "GATEIN_END",
            "GATEOUT_START",
            "GATEOUT_END",
            "DELIVERED",
            "RETURN",
            "OTHER",
            "OUT_FOR_DELIVERY",
            "EXCEPTION",
            "FLIGHT_BOOKED",
            "MANIFEST_READY",
            "RCVD_FROM_SHIPPER",
            "CONSIGNEE_NOTIFIED",
            "EVENT_EST_UPD",
            "EMISSION",
            "CUSTOMS_HOLD_START",
            "CUSTOMS_HOLD_END",
            "TECHNICAL_USE",
            "PICKUP_END",
            "GATEOUT_EMPTY",
            "GATEIN_FULL",
