{
  "swagger": "2.0",
  "info": {
    "title": "Consumer API to Request for Planning in External System",
    "description": "Provides functionality for managing documents for the transportation planning process when integrating SAP Business Network for Logistics with external systems.\nThis specification describes the API from the perspective of SAP Business Network for Logistics as the consumer of the API.\nSAP Business Network for Logistics calls the defined endpoints within other systems.\n",
    "version": "1.0.5",
    "contact": {
      "name": "lbn@sap.com"
    },
    "termsOfService": ""
  },
  "x-sap-shortText": "Enables carriers to manage the transportation planning process in their system.",
  "x-servers": [
    {
      "url": "https://{host}/{basePath}",
      "description": "Test system endpoint",
      "templates": {
        "host": {
          "description": "Test system host"
        },
        "basePath": {
          "description": "Test system base path"
        }
      }
    }
  ],
  "securityDefinitions": {
    "BearerAuth": {
      "type": "apiKey",
      "in": "header",
      "name": "authorization",
      "description": "JWT authorization header"
    }
  },
  "security": [
    {
      "BearerAuth": []
    }
  ],
  "schemes": [
    "https"
  ],
  "produces": [
    "application/json"
  ],
  "consumes": [
    "application/json"
  ],
  "tags": [
    {
      "name": "Consumer API Endpoints for Transportation Document Replication"
    }
  ],
  "paths": {
    "/TransportationDocument": {
      "post": {
        "tags": [
          "Transportation Document Replication Upsert to External System"
        ],
        "consumes": [
          "application/json"
        ],
        "summary": "Consumer API to replicate freight documents from SAP Business Network for Logistics to the external system",
        "description": "Consumer API to replicate Freight Documents from LBN to external system\n",
        "responses": {
          "200": {
            "schema": {
              "$ref": "#/definitions/ResponseStructure"
            },
            "description": "Request has been successfully accepted"
          },
          "400": {
            "description": "Bad request",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "401": {
            "description": "Unauthorized",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "403": {
            "description": "Forbidden",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "500": {
            "description": "Internal Server Error"
          }
        },
        "parameters": [
          {
            "in": "body",
            "name": "body",
            "description": "External planning payload structure to create or update a transportation document in your system",
            "required": true,
            "schema": {
              "$ref": "#/definitions/PostTransportationDocument"
            }
          }
        ]
      },
      "delete": {
        "tags": [
          "Transportation Document Cancellation to External System"
        ],
        "consumes": [
          "application/json"
        ],
        "summary": "Transportation document cancellation request to the external system",
        "description": "Transportation Document Cancellation request to External System\n",
        "responses": {
          "200": {
            "schema": {
              "$ref": "#/definitions/ResponseStructure"
            },
            "description": "Cancellation request successfully accepted"
          },
          "400": {
            "description": "Bad request",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "401": {
            "description": "Unauthorized",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "403": {
            "description": "Forbidden",
            "schema": {
              "$ref": "#/definitions/Error"
            }
          },
          "500": {
            "description": "Internal Server Error"
          }
        },
        "parameters": [
          {
            "in": "body",
            "name": "body",
            "description": "External planning payload structure to cancel a transportation document in your system",
            "required": true,
            "schema": {
              "$ref": "#/definitions/DeleteTransportationDocument"
            }
          }
        ]
      }
    }
  },
  "definitions": {
    "PostTransportationDocument": {
      "allOf": [
        {
          "type": "object",
          "required": [
            "technicalId",
            "senderParty",
            "originatorId",
            "recipientParty",
            "documentRecipientParty",
            "transportationDocument"
          ],
          "properties": {
            "technicalId": {
              "type": "string",
              "maxLength": 255,
              "description": "A unique standard identifier for the Transporatation Document.\n"
            },
            "senderParty": {
              "$ref": "#/definitions/PartyDetails"
            },
            "originatorId": {
              "$ref": "#/definitions/OriginatorId"
            },
            "recipientParty": {
              "$ref": "#/definitions/PartyDetails"
            },
            "documentRecipientParty": {
              "$ref": "#/definitions/PartyDetails"
            },
            "transportationDocument": {
              "$ref": "#/definitions/TransportationDocument"
            }
          }
        }
      ]
    },
    "DeleteTransportationDocument": {
      "type": "object",
      "description": "Document information.",
      "required": [
        "technicalId",
        "senderParty",
        "recipientParty",
        "documentRecipientParty"
      ],
      "properties": {
        "technicalId": {
          "type": "string",
          "maxLength": 255
        },
        "senderParty": {
          "$ref": "#/definitions/PartyDetails"
        },
        "recipientParty": {
          "$ref": "#/definitions/PartyDetails"
        },
        "documentRecipientParty": {
          "$ref": "#/definitions/PartyDetails"
        },
        "creationDateTimeUTC": {
          "type": "string",
          "maxLength": 24,
          "format": "yyyy-MM-ddTHH:mm:ssZ"
        }
      }
    },
    "ResponseStructure": {
      "type": "object",
      "properties": {
        "responseId": {
          "type": "string",
          "maxLength": 30,
